  VALUES(v_company,v_finance_actor,'finance.journals_reports','TANPA_AKSES',v_actor,v_actor)
  ON CONFLICT(company_id,user_id,permission_key) DO UPDATE
    SET restriction_preset='TANPA_AKSES',updated_by=excluded.updated_by,
      master_version=current_override.master_version+1,
      updated_at=clock_timestamp();
  v_permission:=private.acp_resolve_permission(
    v_company,v_finance_actor,'finance.journals_reports');
  IF v_permission->>'roleCode'<>'FINANCE'
    OR COALESCE((v_permission->'effectiveCapabilities')?'POST',false) THEN
    RAISE EXCEPTION 'TEST_FAILED: Finance restriction fixture invalid %',v_permission;
  END IF;
  v_blocked:=false;
  BEGIN
    PERFORM public.post_backoffice_sales_invoice(v_dp_id,
      (v_dp->'data'->>'masterVersion')::bigint,gen_random_uuid());
  EXCEPTION WHEN OTHERS THEN v_blocked:=SQLERRM LIKE '%CUSTOM_PERMISSION_DENIED%'; END;
  IF NOT v_blocked THEN
    RAISE EXCEPTION 'TEST_FAILED: custom Finance denial did not block Invoice posting';
  END IF;
  DELETE FROM public.user_company_permission_overrides override_state
  WHERE override_state.company_id=v_company AND override_state.user_id=v_finance_actor
    AND override_state.permission_key='finance.journals_reports';
  v_permission:=private.acp_resolve_permission(
    v_company,v_finance_actor,'finance.journals_reports');
  IF NOT COALESCE((v_permission->'effectiveCapabilities')?'POST',false) THEN
    RAISE EXCEPTION 'TEST_FAILED: Finance baseline POST capability missing %',v_permission;
  END IF;
  v_blocked:=false;
  BEGIN
    PERFORM public.post_backoffice_sales_invoice(v_dp_id,
      (v_dp->'data'->>'masterVersion')::bigint+1,gen_random_uuid());
  EXCEPTION WHEN OTHERS THEN v_blocked:=SQLERRM LIKE '%MASTER_VERSION_CONFLICT%'; END;
  IF NOT v_blocked THEN RAISE EXCEPTION 'TEST_FAILED: stale DP posting was accepted'; END IF;
  v_dp_posted:=public.post_backoffice_sales_invoice(v_dp_id,
    (v_dp->'data'->>'masterVersion')::bigint,gen_random_uuid());
  IF v_dp_posted->'data'->>'status'<>'POSTED'
    OR v_dp_posted->'data'->>'invoiceNo' NOT LIKE 'INV-'||to_char(v_period_date,'YYYYMMDD')||'-%'
    OR v_dp_posted->'finance'->>'status'<>'POSTED' THEN
    RAISE EXCEPTION 'TEST_FAILED: DP Invoice was not posted canonically';
  END IF;
  PERFORM set_config('request.jwt.claim.sub',v_actor::text,true);
  PERFORM set_config('request.jwt.claim.role','authenticated',true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object(
    'sub',v_actor,'role','authenticated')::text,true);
  INSERT INTO public.user_active_company_contexts(user_id,company_id)
  VALUES(v_actor,v_company) ON CONFLICT(user_id) DO UPDATE
    SET company_id=excluded.company_id,selected_at=clock_timestamp(),updated_at=clock_timestamp();
  IF auth.uid() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: Super Admin JWT identity restore mismatch';
  END IF;
  SELECT dp.grand_total INTO v_dp_total FROM public.backoffice_sales_invoices dp
  WHERE dp.company_id=v_company AND dp.id=v_dp_id;

  v_regular:=public.save_backoffice_sales_invoice_draft(NULL,NULL,gen_random_uuid(),v_order,
    jsonb_build_object('invoiceType','REGULAR','invoiceDate',v_period_date,
      'lines',jsonb_build_array(jsonb_build_object('salesOrderLineId',v_order_line,
        'quantityUom',2,'unitPrice',100000,'discountAmount',10000))));
  v_regular_id:=(v_regular->'data'->>'id')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_receivable_schedules schedule
      WHERE schedule.company_id=v_company AND schedule.invoice_id=v_regular_id)
    OR EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_receivable_schedules schedule
      WHERE schedule.company_id=v_company AND schedule.invoice_id=v_regular_id
        AND schedule.original_amount_due IS DISTINCT FROM schedule.amount_due) THEN
    RAISE EXCEPTION 'TEST_FAILED: fresh Regular schedule original amount bridge invalid';
  END IF;
  IF (v_regular->'data'->>'downPaymentDeductionTotal')::numeric<>v_dp_total
    OR jsonb_array_length(v_regular->'data'->'downPaymentApplications')<>1 THEN
    RAISE EXCEPTION 'TEST_FAILED: posted DP was not auto-filled on Regular Draft';
  END IF;
  v_manual_amount:=round(v_dp_total/2,4);
  v_adjusted:=public.set_backoffice_sales_invoice_down_payments(v_regular_id,
    (v_regular->'data'->>'masterVersion')::bigint,gen_random_uuid(),
    jsonb_build_array(jsonb_build_object('downPaymentInvoiceId',v_dp_id,
      'appliedAmount',v_manual_amount)));
  IF (v_adjusted->'data'->>'downPaymentDeductionTotal')::numeric<>v_manual_amount
    OR (SELECT round(sum(application.applied_basis_amount+application.applied_tax_amount),4)
      FROM public.backoffice_sales_down_payment_applications application
      WHERE application.company_id=v_company AND application.regular_invoice_id=v_regular_id
        AND application.status='HELD')<>v_manual_amount
    OR (SELECT round(sum(tax.applied_tax_amount),4)
      FROM public.backoffice_sales_down_payment_application_tax_breakdowns tax
      JOIN public.backoffice_sales_down_payment_applications application
        ON application.company_id=tax.company_id AND application.id=tax.application_id
      WHERE tax.company_id=v_company AND application.regular_invoice_id=v_regular_id)
      <>round((SELECT sum(application.applied_tax_amount)
        FROM public.backoffice_sales_down_payment_applications application
        WHERE application.company_id=v_company
          AND application.regular_invoice_id=v_regular_id),4) THEN
    RAISE EXCEPTION 'TEST_FAILED: editable DP split or tax lineage invalid';
  END IF;
  v_regular_posted:=public.post_backoffice_sales_invoice(v_regular_id,
    (v_adjusted->'data'->>'masterVersion')::bigint,gen_random_uuid());
  IF v_regular_posted->'data'->>'status'<>'POSTED'
    OR (SELECT draft_invoice_allocated_base_qty FROM public.backoffice_sales_order_lines
      WHERE company_id=v_company AND id=v_order_line)<>0
    OR (SELECT invoiced_base_qty FROM public.backoffice_sales_order_lines
      WHERE company_id=v_company AND id=v_order_line)<>2*v_factor
    OR EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_quantity_allocations allocation
      WHERE allocation.company_id=v_company AND allocation.invoice_id=v_regular_id
        AND allocation.status<>'POSTED')
    OR EXISTS(SELECT 1 FROM public.backoffice_sales_down_payment_applications application
      WHERE application.company_id=v_company AND application.regular_invoice_id=v_regular_id
        AND application.status<>'POSTED') THEN
    RAISE EXCEPTION 'TEST_FAILED: Regular posting final state invalid';
  END IF;
  SELECT journal.* INTO v_journal FROM public.finance_journals journal
  WHERE journal.company_id=v_company
    AND journal.id=(v_regular_posted->'finance'->>'journalId')::uuid;
  SELECT invoice.* INTO STRICT v_invoice_row FROM public.backoffice_sales_invoices invoice
  WHERE invoice.company_id=v_company AND invoice.id=v_regular_id;
  SELECT event.* INTO STRICT v_invoice_event FROM public.financial_events event
  WHERE event.company_id=v_company AND event.id=v_invoice_row.financial_event_id;
  v_revenue_account:=private.resolve_financial_event_account(
    v_invoice_event,'SALES_REVENUE');
  v_discount_account:=private.resolve_financial_event_account(
    v_invoice_event,'SALES_DISCOUNT');
  SELECT round(COALESCE(sum(line.credit-line.debit),0),4)
    INTO v_revenue_credit FROM public.finance_journal_lines line
  WHERE line.company_id=v_company AND line.journal_id=v_journal.id
    AND line.account_id=v_revenue_account;
  SELECT round(COALESCE(sum(line.debit-line.credit),0),4)
    INTO v_discount_debit FROM public.finance_journal_lines line
  WHERE line.company_id=v_company AND line.journal_id=v_journal.id
    AND line.account_id=v_discount_account;
  IF v_journal.status<>'POSTED' OR round(v_journal.total_debit,4)<>round(v_journal.total_credit,4)
    OR v_invoice_row.discount_total<=0
    OR round(v_revenue_credit,4)<>round(v_invoice_row.charge_total,4)
    OR round(v_discount_debit,4)<>round(v_invoice_row.discount_total,4)
    OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines line
      WHERE line.company_id=v_company AND line.journal_id=v_journal.id
        AND line.account_id=v_tax_account AND line.debit>0)
    OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines line
      WHERE line.company_id=v_company AND line.journal_id=v_journal.id
        AND line.account_id=v_tax_account AND line.credit>0) THEN
    RAISE EXCEPTION 'TEST_FAILED: balanced explicit DP tax debit/current tax credit missing';
  END IF;
  v_retry:=public.post_backoffice_sales_invoice(v_regular_id,
    (v_adjusted->'data'->>'masterVersion')::bigint,
    (SELECT operation.operation_id FROM public.backoffice_sales_invoice_operations operation
      WHERE operation.company_id=v_company AND operation.invoice_id=v_regular_id
        AND operation.operation_type='POST'));
  IF COALESCE((v_retry->>'exactRetry')::boolean,false) IS NOT TRUE
    OR (SELECT count(*) FROM public.finance_journals journal
      WHERE journal.company_id=v_company AND journal.financial_event_id=
        (v_regular_posted->'data'->>'financialEventId')::uuid)<>1 THEN
    RAISE EXCEPTION 'TEST_FAILED: exact retry duplicated posting';
  END IF;
  IF (SELECT count(*) FROM public.sales_headers)<>v_sales_before THEN
    RAISE EXCEPTION 'TEST_FAILED: Backoffice posting changed POS Sales';
  END IF;
  IF (SELECT count(*) FROM public.financial_events)<>v_event_before+2
    OR (SELECT count(*) FROM public.finance_journals)<>v_journal_before+2 THEN
    RAISE EXCEPTION 'TEST_FAILED: Invoice posting effect count invalid';
  END IF;
  PERFORM set_config('mads_test.invoice_revision_behavior_seed',v_regular_id::text,true);
  PERFORM set_config('mads_test.invoice_revision_amount_taxed',v_regular_id::text,true);
  UPDATE public.warehouses SET allow_negative_stock=v_original_negative
  WHERE company_id=v_company AND id=v_warehouse;
END
$test$;
SELECT 'backoffice_sales_invoice_posting_runtime_behavior' check_name,'PASS' status,
  0::bigint violation_rows,jsonb_build_object('tested',ARRAY[
    'canonical taxed SO preparation','fresh Draft schedule original amount bridge',
    'stale posting denial','DP Invoice posting',
    'local strict Finance role and custom override denial',
    'shared canonical Invoice numbering','auto oldest available DP application',
    'editable DP application','DP basis and per-account tax lineage',
    'Regular quantity hold finalization','gross Regular Invoice Revenue and Sales Discount',
    'balanced AR Advance Revenue and tax journal',
    'explicit DP tax debit and current Invoice tax credit','exact posting retry',
    'POS Sales unchanged','all fixture writes rolled back']) details;

-- Authenticated rollback-only behavior test for posted Invoice price correction.
-- Uses one eligible existing Posted Invoice, writes two opposite corrections,
-- asserts their effects, and rolls the entire transaction back.
DO $test$
DECLARE v_actor uuid;v_company uuid;v_invoice public.backoffice_sales_invoices%rowtype;
  v_context jsonb;v_payload jsonb;v_reverse_payload jsonb;v_result jsonb;v_reverse jsonb;v_retry jsonb;
  v_operation uuid:=gen_random_uuid();v_first_line uuid;v_original_price numeric(24,4);
  v_invoice_before jsonb;v_lines_before jsonb;v_event_before bigint;v_journal_before bigint;
  v_stock_before bigint;v_delta numeric(24,4);v_journal public.finance_journals%rowtype;
  v_blocked boolean:=false;v_correction_id uuid;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM private.kgs_schema_migrations WHERE version='20260928110000') THEN
    RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: migration 20260928110000 missing';
  END IF;
  SELECT profile.id INTO v_actor FROM public.profiles profile
  JOIN auth.users auth_user ON auth_user.id=profile.id
  WHERE profile.role='super_admin'::public.user_role ORDER BY profile.id LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: linked Super Admin required'; END IF;

  SELECT invoice.* INTO v_invoice FROM public.backoffice_sales_invoices invoice
  WHERE invoice.id=NULLIF(current_setting('mads_test.invoice_revision_behavior_seed',true),'')::uuid
    AND invoice.company_id IN('4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8'::uuid,
      '07bdffb9-8c56-444c-a49b-81ac86745674'::uuid,'809abdd9-d05f-4525-9726-1951a0ae1a81'::uuid)
    AND invoice.status='POSTED' AND invoice.invoice_type='REGULAR'
    AND EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_lines line
      WHERE line.company_id=invoice.company_id AND line.invoice_id=invoice.id
        AND line.line_type='PRODUCT' AND line.source_kind='SALES_ORDER')
    AND EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_receivable_schedules schedule
      WHERE schedule.company_id=invoice.company_id AND schedule.invoice_id=invoice.id)
    AND NOT EXISTS(SELECT 1 FROM public.backoffice_sales_credit_notes note
      WHERE note.company_id=invoice.company_id AND note.source_invoice_id=invoice.id
        AND note.status IN('DRAFT','POSTED'))
    AND NOT EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_price_corrections correction
      WHERE correction.company_id=invoice.company_id AND correction.source_invoice_id=invoice.id)
  ORDER BY invoice.posted_at DESC,invoice.id LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: eligible KMS/LSM/SMS Posted Regular Invoice without Return Credit Note required';
  END IF;
  v_company:=v_invoice.company_id;
  PERFORM set_config('request.jwt.claim.sub',v_actor::text,true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_actor,'role','authenticated')::text,true);
  INSERT INTO public.user_active_company_contexts(user_id,company_id) VALUES(v_actor,v_company)
  ON CONFLICT(user_id) DO UPDATE SET company_id=excluded.company_id,
    selected_at=clock_timestamp(),updated_at=clock_timestamp();

  SELECT to_jsonb(invoice) INTO v_invoice_before FROM public.backoffice_sales_invoices invoice
  WHERE invoice.company_id=v_company AND invoice.id=v_invoice.id;
  SELECT jsonb_agg(to_jsonb(line) ORDER BY line.line_no,line.id) INTO v_lines_before
  FROM public.backoffice_sales_invoice_lines line
  WHERE line.company_id=v_company AND line.invoice_id=v_invoice.id;
  SELECT count(*) INTO v_event_before FROM public.financial_events;
  SELECT count(*) INTO v_journal_before FROM public.finance_journals;
  SELECT count(*) INTO v_stock_before FROM public.stock_movements;

  v_context:=public.get_backoffice_sales_invoice_price_correction_context(v_invoice.id);
  IF (v_context->>'priceRevision')::bigint<>0 OR NOT (v_context->>'canCorrect')::boolean THEN
    RAISE EXCEPTION 'TEST_FAILED: initial correction context invalid';
  END IF;
  SELECT line.id,private.backoffice_invoice_effective_entered_unit_price(v_company,line.id)
  INTO v_first_line,v_original_price FROM public.backoffice_sales_invoice_lines line
  WHERE line.company_id=v_company AND line.invoice_id=v_invoice.id
    AND line.line_type='PRODUCT' AND line.source_kind='SALES_ORDER'
  ORDER BY line.line_no,line.id LIMIT 1;
  SELECT jsonb_agg(jsonb_build_object('invoiceLineId',line.id,'newUnitPrice',
      private.backoffice_invoice_effective_entered_unit_price(v_company,line.id)
        +CASE WHEN line.id=v_first_line THEN 100 ELSE 0 END) ORDER BY line.line_no,line.id)
  INTO v_payload FROM public.backoffice_sales_invoice_lines line
  WHERE line.company_id=v_company AND line.invoice_id=v_invoice.id
    AND line.line_type='PRODUCT' AND line.source_kind='SALES_ORDER';

  v_result:=public.post_backoffice_sales_invoice_price_correction(v_invoice.id,
    v_invoice.master_version,0,v_operation,v_payload);
  v_delta:=(v_result->>'totalDelta')::numeric;
  v_correction_id:=(v_result->>'correctionId')::uuid;
  IF v_delta<=0 OR v_result->>'kind'<>'DEBIT_NOTE'
    OR (v_result->'priceCorrectionContext'->>'priceRevision')::bigint<>1
    OR private.backoffice_invoice_effective_entered_unit_price(v_company,v_first_line)<>v_original_price+100 THEN
    RAISE EXCEPTION 'TEST_FAILED: Debit Note correction or effective price invalid';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_price_corrections correction
      WHERE correction.company_id=v_company AND correction.id=v_correction_id
        AND correction.total_delta=correction.ar_adjustment_amount-correction.refund_liability_amount
        AND correction.ar_adjustment_amount>=0 AND correction.refund_liability_amount<=0) THEN
    RAISE EXCEPTION 'TEST_FAILED: Debit Note AR/refund settlement split invalid';
  END IF;
  SELECT * INTO v_journal FROM public.finance_journals journal
  WHERE journal.company_id=v_company AND journal.journal_no=v_result->>'journalNo';
  IF v_journal.status<>'POSTED' OR round(v_journal.total_debit,4)<>round(v_journal.total_credit,4)
    OR round(v_journal.total_debit,4)<>round(v_delta,4) THEN
    RAISE EXCEPTION 'TEST_FAILED: Debit Note Journal invalid';
  END IF;
  IF (public.get_backoffice_sales_invoice_payment_context(v_invoice.id)->'summary'->>'effectiveInvoiceAmount')::numeric
      <>v_invoice.grand_total+v_delta THEN
    RAISE EXCEPTION 'TEST_FAILED: payment context did not use effective Invoice total';
  END IF;

  v_retry:=public.post_backoffice_sales_invoice_price_correction(v_invoice.id,
    v_invoice.master_version,0,v_operation,v_payload);
  IF COALESCE((v_retry->>'exactRetry')::boolean,false) IS NOT TRUE
    OR (SELECT count(*) FROM public.backoffice_sales_invoice_price_corrections correction
      WHERE correction.company_id=v_company AND correction.id=v_correction_id)<>1 THEN
    RAISE EXCEPTION 'TEST_FAILED: exact retry duplicated correction';
  END IF;
  BEGIN
    PERFORM public.post_backoffice_sales_invoice_price_correction(v_invoice.id,
      v_invoice.master_version,0,gen_random_uuid(),v_payload);
  EXCEPTION WHEN OTHERS THEN v_blocked:=SQLERRM LIKE '%INVOICE_PRICE_REVISION_CONFLICT%'; END;
  IF NOT v_blocked THEN RAISE EXCEPTION 'TEST_FAILED: stale price revision was not rejected'; END IF;

  SELECT jsonb_agg(jsonb_build_object('invoiceLineId',line.id,'newUnitPrice',
      CASE WHEN line.id=v_first_line THEN v_original_price
        ELSE private.backoffice_invoice_effective_entered_unit_price(v_company,line.id) END)
      ORDER BY line.line_no,line.id)
  INTO v_reverse_payload FROM public.backoffice_sales_invoice_lines line
  WHERE line.company_id=v_company AND line.invoice_id=v_invoice.id
    AND line.line_type='PRODUCT' AND line.source_kind='SALES_ORDER';
  v_reverse:=public.post_backoffice_sales_invoice_price_correction(v_invoice.id,
    v_invoice.master_version,1,gen_random_uuid(),v_reverse_payload);
  IF v_reverse->>'kind'<>'CREDIT_NOTE' OR (v_reverse->>'totalDelta')::numeric<>-v_delta
    OR (v_reverse->'priceCorrectionContext'->>'priceRevision')::bigint<>2
    OR (v_reverse->>'effectiveTotal')::numeric<>v_invoice.grand_total THEN
    RAISE EXCEPTION 'TEST_FAILED: reverse price correction did not restore effective total';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_price_corrections correction
      WHERE correction.company_id=v_company AND correction.id=(v_reverse->>'correctionId')::uuid
        AND correction.total_delta=correction.ar_adjustment_amount-correction.refund_liability_amount
        AND correction.ar_adjustment_amount<=0 AND correction.refund_liability_amount>=0) THEN
    RAISE EXCEPTION 'TEST_FAILED: Credit Note AR/refund settlement split invalid';
  END IF;

  v_blocked:=false;
  BEGIN
    UPDATE public.backoffice_sales_invoice_price_corrections SET total_delta=total_delta
    WHERE company_id=v_company AND id=v_correction_id;
  EXCEPTION WHEN OTHERS THEN v_blocked:=SQLERRM LIKE '%POSTED_INVOICE_PRICE_CORRECTION_IMMUTABLE%'; END;
  IF NOT v_blocked THEN RAISE EXCEPTION 'TEST_FAILED: posted correction history is mutable'; END IF;
  IF (SELECT to_jsonb(invoice) FROM public.backoffice_sales_invoices invoice
      WHERE invoice.company_id=v_company AND invoice.id=v_invoice.id) IS DISTINCT FROM v_invoice_before
    OR (SELECT jsonb_agg(to_jsonb(line) ORDER BY line.line_no,line.id)
      FROM public.backoffice_sales_invoice_lines line
      WHERE line.company_id=v_company AND line.invoice_id=v_invoice.id) IS DISTINCT FROM v_lines_before THEN
    RAISE EXCEPTION 'TEST_FAILED: original Invoice or lines were mutated';
  END IF;
  IF (SELECT count(*) FROM public.stock_movements)<>v_stock_before
    OR (SELECT count(*) FROM public.financial_events)<>v_event_before+2
    OR (SELECT count(*) FROM public.finance_journals)<>v_journal_before+2 THEN
    RAISE EXCEPTION 'TEST_FAILED: Stock mutation or Finance effect count invalid';
  END IF;
END
$test$;

SELECT 'backoffice_posted_invoice_price_correction_behavior' check_name,'PASS' status,
  0::bigint violation_rows,jsonb_build_object('tested',ARRAY[
    'authenticated existing Posted Invoice correction','server timestamped Debit Note',
    'balanced delta Journal','signed AR/refund settlement split','effective payment context','exact retry',
    'stale price revision rejection','Credit Note restores original effective total',
    'posted correction immutability','original Invoice and lines immutable',
    'no Stock movement','all transactional writes rolled back']) details;

-- Authenticated, self-contained and rollback-only payment collection behavior.
-- Run only after migration 20260911160000 on isolated Development.
DO $test$
DECLARE v_actor uuid;v_company uuid;v_store uuid;v_warehouse uuid;v_customer uuid;
  v_customer_category uuid;v_fixture_code text;
  v_product_uom uuid;v_product uuid;v_method uuid;v_today date;v_topup numeric;
  v_stock_after numeric;v_batch_id uuid:=gen_random_uuid();v_movement_id uuid:=gen_random_uuid();
  v_created jsonb;v_confirmed jsonb;v_dispatched jsonb;v_received jsonb;
  v_invoice_draft jsonb;v_invoice_posted jsonb;v_receipt_one jsonb;v_post_one jsonb;
  v_receipt_two jsonb;v_post_two jsonb;v_retry jsonb;v_order uuid;v_order_line uuid;
  v_workspace jsonb;v_aging jsonb;v_statement jsonb;
  v_delivery uuid;v_delivery_line uuid;v_invoice uuid;v_version bigint;
  v_grand numeric;v_first numeric;v_second numeric;v_event uuid;v_journal uuid;
  v_post_key_one uuid:=gen_random_uuid();v_post_key_two uuid:=gen_random_uuid();
  v_retail_alloc_before bigint;v_sales_before bigint;v_failed boolean:=false;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM private.kgs_schema_migrations WHERE version='20260911163000') THEN
    RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: 20260911163000 unified AR reporting integration required';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM private.kgs_schema_migrations WHERE version='20260911161000') THEN
    RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: 20260911161000 payment account mapping fix required';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM private.kgs_schema_migrations WHERE version='20260911162000') THEN
    RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: 20260911162000 Invoice payment UI runtime required';
  END IF;
  SELECT profile.id INTO v_actor FROM public.profiles profile
  JOIN auth.users actor ON actor.id=profile.id
  WHERE profile.role='super_admin'::public.user_role ORDER BY profile.id LIMIT 1;
  SELECT company.id,store.id,warehouse.id,product_uom.id,
    product_uom.product_id,method.id,
    (clock_timestamp() AT TIME ZONE company.timezone)::date
  INTO v_company,v_store,v_warehouse,v_product_uom,v_product,v_method,v_today
  FROM public.companies company
  JOIN public.stores store ON store.company_id=company.id AND store.status='ACTIVE'
  JOIN public.warehouses warehouse ON warehouse.company_id=company.id
    AND warehouse.is_active AND warehouse.is_sale_source
    AND (warehouse.store_id IS NULL OR warehouse.store_id=store.id)
  JOIN public.product_uoms product_uom ON product_uom.company_id=company.id
    AND product_uom.is_active AND product_uom.sales_allowed AND product_uom.factor_to_base=1
  JOIN public.products product ON product.company_id=product_uom.company_id
    AND product.id=product_uom.product_id AND product.is_active AND NOT product.is_bundle
    AND product.uom_id=product_uom.uom_id
  JOIN LATERAL(
    SELECT payment_method.id
    FROM public.payment_methods payment_method
    WHERE payment_method.company_id=company.id AND payment_method.is_active
      AND payment_method.settlement_route IN('DIRECT_BANK','CASH_DRAWER')
    ORDER BY CASE payment_method.settlement_route WHEN 'DIRECT_BANK' THEN 1 ELSE 2 END,
      payment_method.id LIMIT 1
  ) method ON true
  WHERE company.status='ACTIVE' AND company.id='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8'::uuid
    AND EXISTS(SELECT 1 FROM public.accounting_periods period
      WHERE period.company_id=company.id AND period.status IN('OPEN','REOPENED')
        AND (clock_timestamp() AT TIME ZONE company.timezone)::date
          BETWEEN period.start_date AND period.end_date)
  ORDER BY company.id,store.id,warehouse.id,product_uom.id LIMIT 1;
  IF v_actor IS NULL OR v_company IS NULL THEN
    RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: canonical Company, Product-UOM, Warehouse, Payment Method and current open period required';
  END IF;
  PERFORM set_config('request.jwt.claim.sub',v_actor::text,true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object(
    'sub',v_actor,'role','authenticated')::text,true);
  INSERT INTO public.user_active_company_contexts(user_id,company_id)
  VALUES(v_actor,v_company) ON CONFLICT(user_id) DO UPDATE
    SET company_id=excluded.company_id,selected_at=clock_timestamp(),updated_at=clock_timestamp();

  SELECT customer.id INTO v_customer
  FROM public.customers customer
  WHERE customer.company_id=v_company AND customer.is_active
    AND NOT customer.is_system_customer
  ORDER BY customer.id LIMIT 1;
  IF v_customer IS NULL THEN
    SELECT category.id INTO v_customer_category
    FROM public.customer_categories category
    WHERE category.company_id=v_company AND category.is_active
    ORDER BY category.is_system_category DESC,category.id LIMIT 1;
    IF v_customer_category IS NULL THEN
      RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: canonical active Customer Category required';
    END IF;
    v_fixture_code:='PAYTEST-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
    v_created:=public.save_customer_with_pricelist(
      NULL,NULL,v_fixture_code,'Payment Collection Rollback Customer',
      v_customer_category,NULL,NULL,NULL,'BUSINESS',0,NULL,
      'Rollback-only payment collection fixture',TRUE,NULL,NULL);
    v_customer:=(v_created->>'customerId')::uuid;
    IF v_customer IS NULL OR NOT EXISTS(
      SELECT 1 FROM public.customers customer
      WHERE customer.company_id=v_company AND customer.id=v_customer
        AND customer.code=v_fixture_code AND customer.is_active
        AND NOT customer.is_system_customer
    ) THEN
      RAISE EXCEPTION 'TEST_FAILED: canonical rollback Customer fixture was not created';
    END IF;
  END IF;
  INSERT INTO public.company_features(company_id,feature_code,is_enabled,config,updated_by)
  VALUES(v_company,'backoffice_delivered_qty_sales_enabled',true,'{}',v_actor)
  ON CONFLICT(company_id,feature_code) DO UPDATE
    SET is_enabled=true,updated_by=excluded.updated_by;

  IF NOT EXISTS(SELECT 1 FROM public.company_sales_process_settings WHERE company_id=v_company AND active_mode='BACKOFFICE_DELIVERED_QTY_INVOICE') THEN RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: KMS Backoffice mode required'; END IF;
  PERFORM private.assert_sales_process_root_creation_allowed(
    v_company,'BACKOFFICE_DELIVERED_QTY_INVOICE');

  SELECT COALESCE(stock_qty,0) INTO v_stock_after FROM public.product_stocks
  WHERE company_id=v_company AND warehouse_id=v_warehouse AND product_id=v_product;
  v_topup:=CASE WHEN COALESCE(v_stock_after,0)<10 THEN 10-COALESCE(v_stock_after,0) ELSE 10 END;
  INSERT INTO public.product_stocks(product_id,warehouse_id,stock_qty,company_id)
  VALUES(v_product,v_warehouse,v_topup,v_company)
  ON CONFLICT(product_id,warehouse_id) DO UPDATE
    SET stock_qty=public.product_stocks.stock_qty+excluded.stock_qty,
      updated_at=clock_timestamp();
  INSERT INTO public.product_batches(id,product_id,warehouse_id,qty_purchased,
    qty_remaining,cogs_unit,company_id)
  SELECT v_batch_id,v_product,v_warehouse,v_topup,v_topup,
    GREATEST(COALESCE(product.cogs,1),1),v_company
  FROM public.products product WHERE product.company_id=v_company AND product.id=v_product;
  SELECT stock_qty INTO STRICT v_stock_after FROM public.product_stocks
  WHERE company_id=v_company AND warehouse_id=v_warehouse AND product_id=v_product;
  INSERT INTO public.stock_movements(id,product_id,warehouse_id,qty_change,
    movement_type,reference_table,reference_id,company_id,base_uom_id,
    base_uom_name_snapshot,balance_after_base_qty,actor_id,posted_at,
    movement_status,source_line_id,notes)
  SELECT v_movement_id,v_product,v_warehouse,v_topup,
    'PURCHASE'::public.stock_movement_type,'BACKOFFICE_PAYMENT_COLLECTION_TEST',v_batch_id,
    v_company,product.uom_id,uom.name,v_stock_after,v_actor,clock_timestamp(),
    'POSTED',v_batch_id,'Rollback-only payment collection fixture'
  FROM public.products product JOIN public.uoms uom
    ON uom.company_id=product.company_id AND uom.id=product.uom_id
  WHERE product.company_id=v_company AND product.id=v_product;

  SELECT count(*) INTO v_retail_alloc_before FROM public.customer_receipt_allocations;
  SELECT count(*) INTO v_sales_before FROM public.sales_headers;
  v_created:=public.save_backoffice_sales_order_draft(NULL,NULL,gen_random_uuid(),
    jsonb_build_object('storeId',v_store,'warehouseId',v_warehouse,'customerId',v_customer,
      'selectedPricelistId',NULL,'orderDate',v_today,'plannedDeliveryDate',v_today,
      'isTempo',true,'dueDate',v_today+14,'currencyCode','IDR','globalDiscount',0,
      'deliveryFeeAmount',0,'roundingDirection','NONE','roundingIncrement',100,
      'lines',jsonb_build_array(jsonb_build_object('productUomId',v_product_uom,
        'quantity',1,'overrideUnitPrice',100000))));
  v_order:=(v_created->'data'->>'id')::uuid;
  v_confirmed:=public.confirm_backoffice_sales_order(v_order,
    (v_created->'data'->>'masterVersion')::bigint,gen_random_uuid());
  SELECT id INTO STRICT v_order_line FROM public.backoffice_sales_order_lines
  WHERE company_id=v_company AND sales_order_id=v_order;
  v_delivery:=(v_confirmed->'fulfillment'->>'deliveryOrderId')::uuid;
  SELECT id INTO STRICT v_delivery_line FROM public.backoffice_sales_delivery_order_lines
  WHERE company_id=v_company AND delivery_order_id=v_delivery;
  SELECT master_version INTO STRICT v_version FROM public.backoffice_sales_delivery_orders
  WHERE company_id=v_company AND id=v_delivery;
  v_dispatched:=public.dispatch_backoffice_sales_delivery(v_delivery,v_version,gen_random_uuid(),
    jsonb_build_array(jsonb_build_object('deliveryLineId',v_delivery_line,'quantityUom',1)),
    'Payment collection rollback fixture');
  SELECT master_version INTO STRICT v_version FROM public.backoffice_sales_delivery_orders
  WHERE company_id=v_company AND id=v_delivery;
  v_received:=public.receive_backoffice_sales_delivery(v_delivery,v_version,gen_random_uuid(),
    v_today,'Payment collection rollback fixture');
  IF v_received->>'deliveryStatus'<>'COMPLETED' THEN
    RAISE EXCEPTION 'TEST_FAILED: Backoffice delivery did not complete';
  END IF;

  v_invoice_draft:=public.save_backoffice_sales_invoice_draft(NULL,NULL,gen_random_uuid(),v_order,
    jsonb_build_object('invoiceType','REGULAR','invoiceDate',v_today,'dueDate',v_today+14,
      'paymentTermId',NULL,'deliveryFeeAmount',0,
      'lines',jsonb_build_array(jsonb_build_object('salesOrderLineId',v_order_line,
        'quantityUom',1,'unitPrice',100000,'discountAmount',0,'taxApplied',false))));
  v_invoice:=(v_invoice_draft->'data'->>'id')::uuid;
  v_invoice_posted:=public.post_backoffice_sales_invoice(v_invoice,
    (v_invoice_draft->'data'->>'masterVersion')::bigint,gen_random_uuid());
  IF v_invoice_posted->'data'->>'status'<>'POSTED'
    OR v_invoice_posted->'finance'->>'status'<>'POSTED' THEN
    RAISE EXCEPTION 'TEST_FAILED: canonical Backoffice Invoice posting failed';
  END IF;
  SELECT grand_total INTO STRICT v_grand FROM public.backoffice_sales_invoices
  WHERE company_id=v_company AND id=v_invoice;
  v_first:=round(v_grand*0.4,4);v_second:=v_grand-v_first;

  v_receipt_one:=public.save_customer_receipt_allocated_draft(NULL,NULL,v_customer,v_today,
    v_method,'PAY-1',NULL,'Partial Backoffice Invoice payment',v_first,
    jsonb_build_array(jsonb_build_object('sourceType','BACKOFFICE_SALES_INVOICE',
      'sourceId',v_invoice,'clientAllocationKey',gen_random_uuid(),'allocatedAmount',v_first)));
  IF EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_receivable_schedules
    WHERE company_id=v_company AND invoice_id=v_invoice AND allocated_payment_amount<>0) THEN
    RAISE EXCEPTION 'TEST_FAILED: Draft receipt changed Invoice outstanding';
  END IF;
  BEGIN
    PERFORM public.post_customer_receipt_unified(
      (v_receipt_one->>'documentId')::uuid,(v_receipt_one->>'masterVersion')::bigint+1,
      gen_random_uuid());
  EXCEPTION WHEN OTHERS THEN v_failed:=SQLERRM LIKE '%MASTER_VERSION_CONFLICT%'; END;
  IF NOT v_failed THEN RAISE EXCEPTION 'TEST_FAILED: stale payment posting was accepted'; END IF;
  v_post_one:=public.post_customer_receipt_unified(
    (v_receipt_one->>'documentId')::uuid,(v_receipt_one->>'masterVersion')::bigint,
    v_post_key_one);
  IF v_post_one->>'status'<>'POSTED'
    OR (SELECT round(sum(allocated_payment_amount),4)
      FROM public.backoffice_sales_invoice_receivable_schedules
      WHERE company_id=v_company AND invoice_id=v_invoice)<>v_first
    OR NOT EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_receivable_schedules
      WHERE company_id=v_company AND invoice_id=v_invoice AND status='PARTIALLY_PAID') THEN
    RAISE EXCEPTION 'TEST_FAILED: first partial payment did not reconcile schedule';
  END IF;

  v_workspace:=public.get_finance_customer_receipts();
  v_aging:=public.get_finance_ar_aging(v_today,v_customer,v_store);
  v_statement:=public.get_finance_customer_statement(v_customer,v_today,v_today,v_store);
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_workspace->'openInvoices') item
      WHERE item->>'sourceType'='BACKOFFICE_SALES_INVOICE'
        AND item->>'sourceId'=v_invoice::text
        AND round((item->>'remainingAmount')::numeric,4)=round(v_second,4))
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_workspace->'allocations') item
      WHERE item->>'source_type'='BACKOFFICE_SALES_INVOICE'
        AND item->>'source_id'=v_invoice::text
        AND round((item->>'allocated_amount')::numeric,4)=round(v_first,4))
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_aging->'invoices') item
      WHERE item->>'sourceProcess'='BACKOFFICE' AND item->>'sourceId'=v_invoice::text
        AND round((item->>'outstanding')::numeric,4)=round(v_second,4))
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_statement->'rows') item
      WHERE item->>'sourceType'='INVOICE' AND item->>'sourceProcess'='BACKOFFICE'
        AND item->>'sourceId'=v_invoice::text)
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_statement->'rows') item
      WHERE item->>'sourceType'='RECEIPT' AND item->>'sourceProcess'='BACKOFFICE'
        AND round((item->>'credit')::numeric,4)=round(v_first,4)) THEN
    RAISE EXCEPTION 'TEST_FAILED: Backoffice Invoice is not reconciled across Receipt workspace, Aging and Statement';
  END IF;

  v_receipt_two:=public.register_backoffice_sales_invoice_payment(v_invoice,v_post_key_two,
    v_today,v_method,v_second,'PAY-2',NULL,'Final Backoffice Invoice payment');
  v_post_two:=v_receipt_two->'payment';
  IF v_post_two->>'status'<>'POSTED'
    OR v_receipt_two->'paymentContext'->'summary'->>'status'<>'PAID'
    OR jsonb_array_length(v_receipt_two->'paymentContext'->'payments')<>2
    OR EXISTS(SELECT 1 FROM public.backoffice_sales_invoice_receivable_schedules
      WHERE company_id=v_company AND invoice_id=v_invoice
        AND (status<>'PAID' OR allocated_payment_amount<>amount_due))
    OR (SELECT round(sum(allocation.allocated_amount),4)
      FROM public.customer_receipt_backoffice_invoice_allocations allocation
      JOIN public.customer_receipt_documents receipt
        ON receipt.company_id=allocation.company_id AND receipt.id=allocation.document_id
       AND receipt.status='POSTED'
      WHERE allocation.company_id=v_company AND allocation.invoice_id=v_invoice)<>round(v_grand,4) THEN
    RAISE EXCEPTION 'TEST_FAILED: final payment did not settle Invoice';
  END IF;
  SELECT financial_event_id INTO STRICT v_event
  FROM public.customer_receipt_documents
  WHERE company_id=v_company AND id=(v_post_two->>'receiptId')::uuid;
  SELECT id INTO STRICT v_journal FROM public.finance_journals
  WHERE company_id=v_company AND financial_event_id=v_event AND status='POSTED';
  IF NOT EXISTS(SELECT 1 FROM public.finance_journals journal
      WHERE journal.company_id=v_company AND journal.id=v_journal
        AND round(journal.total_debit,4)=round(v_second,4)
        AND round(journal.total_credit,4)=round(v_second,4))
    OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines line
      WHERE line.company_id=v_company AND line.journal_id=v_journal
        AND line.debit=v_second AND line.credit=0)
    OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines line
      WHERE line.company_id=v_company AND line.journal_id=v_journal
        AND line.credit=v_second AND line.debit=0) THEN
    RAISE EXCEPTION 'TEST_FAILED: final receipt journal is not balanced';
  END IF;
  v_retry:=public.register_backoffice_sales_invoice_payment(v_invoice,v_post_key_two,
    v_today,v_method,v_second,'PAY-2',NULL,'Final Backoffice Invoice payment');
  IF COALESCE((v_retry->>'exactRetry')::boolean,false) IS NOT TRUE
    OR (SELECT count(*) FROM public.finance_journals
      WHERE company_id=v_company AND financial_event_id=v_event)<>1 THEN
    RAISE EXCEPTION 'TEST_FAILED: exact retry duplicated payment effect';
  END IF;
  v_workspace:=public.get_finance_customer_receipts();
  v_aging:=public.get_finance_ar_aging(v_today,v_customer,v_store);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_workspace->'openInvoices') item
      WHERE item->>'sourceType'='BACKOFFICE_SALES_INVOICE' AND item->>'sourceId'=v_invoice::text)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_aging->'invoices') item
      WHERE item->>'sourceProcess'='BACKOFFICE' AND item->>'sourceId'=v_invoice::text) THEN
    RAISE EXCEPTION 'TEST_FAILED: paid Backoffice Invoice remains open in Receipt workspace or Aging';
  END IF;
  v_failed:=false;
  BEGIN
    PERFORM public.register_backoffice_sales_invoice_payment(v_invoice,gen_random_uuid(),
      v_today,v_method,1,'PAY-OVER',NULL,'Rejected overpayment');
  EXCEPTION WHEN OTHERS THEN v_failed:=SQLERRM LIKE '%CUSTOMER_RECEIPT_OVER_ALLOCATION%'; END;
  IF NOT v_failed THEN RAISE EXCEPTION 'TEST_FAILED: over-allocation was accepted'; END IF;
  IF (SELECT count(*) FROM public.customer_receipt_allocations)<>v_retail_alloc_before
    OR (SELECT count(*) FROM public.sales_headers)<>v_sales_before THEN
    RAISE EXCEPTION 'TEST_FAILED: Backoffice payment changed Retail allocation or Sales';
  END IF;
  PERFORM set_config('mads_test.invoice_revision_amount_untaxed',v_invoice::text,true);
END
$test$;
SELECT 'backoffice_sales_payment_collection_behavior' check_name,'PASS' status,
  0::bigint violation_rows,jsonb_build_object('tested',ARRAY[
    'canonical completed SO and posted Invoice','Draft payment zero final effect',
    'stale version denied','unified post dispatch','partial payment schedule','final settlement schedule',
    'posted allocation reconciliation','balanced Cash/Bank to AR journal',
    'atomic Invoice register payment','payment context and receipt history',
    'unified Receipt workspace','Backoffice AR Aging installment','Customer Statement source tracing',
    'exact retry','over-allocation denied','Retail allocation and Sales unchanged',
    'all fixture writes rolled back']) details;

-- STAGING ROLLBACK-ONLY fixture for the revision preparation behavior test.
-- Creates three additional unpaid Regular Invoices for the same Customer as
-- the canonical DP-backed target. All rows are removed by the outer rollback.
DO $fixture$
DECLARE
  c constant uuid:='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8'::uuid;
  actor uuid:=auth.uid();target public.backoffice_sales_invoices%rowtype;
  v_store uuid;v_warehouse uuid;v_product_uom uuid;v_product uuid;
  v_order uuid;v_order_line uuid;v_delivery uuid;v_delivery_line uuid;
  v_version bigint;v_today date;v_created jsonb;v_confirmed jsonb;v_received jsonb;
  v_invoice jsonb;v_posted jsonb;v_invoice_id uuid;v_batch uuid:=gen_random_uuid();
  v_movement uuid:=gen_random_uuid();v_stock numeric;v_topup numeric;
  v_iteration integer;v_phase text:='fixture_start';
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'TEST_PRECONDITION: auth context required'; END IF;
  v_phase:='select_dp_target';
  SELECT i.* INTO STRICT target FROM public.backoffice_sales_invoices i
  WHERE i.company_id=c
    AND i.id=NULLIF(current_setting('mads_test.invoice_revision_behavior_seed',true),'')::uuid
    AND i.status='POSTED' AND i.invoice_type='REGULAR'
    AND EXISTS(SELECT 1 FROM public.backoffice_sales_down_payment_applications a
      WHERE a.company_id=c AND a.regular_invoice_id=i.id AND a.status='POSTED')
  ORDER BY i.posted_at,i.id LIMIT 1;
  PERFORM set_config('mads_test.invoice_revision_fixture_1',target.id::text,true);

  v_phase:='select_sales_masters';
  SELECT s.id,w.id,pu.id,pu.product_id,
    (clock_timestamp() AT TIME ZONE company.timezone)::date
  INTO STRICT v_store,v_warehouse,v_product_uom,v_product,v_today
  FROM public.companies company
  JOIN public.stores s ON s.company_id=company.id AND s.id=target.store_id
    AND s.status='ACTIVE'
  JOIN public.warehouses w ON w.company_id=company.id AND w.id=target.warehouse_id
    AND w.is_active AND w.is_sale_source
  JOIN public.product_uoms pu ON pu.company_id=company.id AND pu.is_active
    AND pu.sales_allowed AND pu.factor_to_base=1
  JOIN public.products p ON p.company_id=pu.company_id AND p.id=pu.product_id
    AND p.is_active AND NOT p.is_bundle AND p.uom_id=pu.uom_id
  WHERE company.id=c AND company.status='ACTIVE'
  ORDER BY pu.id LIMIT 1;

  SELECT COALESCE(stock.stock_qty,0) INTO v_stock FROM public.product_stocks stock
  WHERE stock.company_id=c AND stock.warehouse_id=v_warehouse AND stock.product_id=v_product;
  v_topup:=CASE WHEN COALESCE(v_stock,0)<6 THEN 6-COALESCE(v_stock,0) ELSE 3 END;
  INSERT INTO public.product_stocks(product_id,warehouse_id,stock_qty,company_id)
  VALUES(v_product,v_warehouse,v_topup,c)
  ON CONFLICT(product_id,warehouse_id) DO UPDATE
    SET stock_qty=public.product_stocks.stock_qty+excluded.stock_qty,
      updated_at=clock_timestamp();
  INSERT INTO public.product_batches(id,product_id,warehouse_id,qty_purchased,
    qty_remaining,cogs_unit,company_id)
  SELECT v_batch,v_product,v_warehouse,v_topup,v_topup,
    GREATEST(COALESCE(p.cogs,1),1),c FROM public.products p
  WHERE p.company_id=c AND p.id=v_product;
  SELECT stock.stock_qty INTO STRICT v_stock FROM public.product_stocks stock
  WHERE stock.company_id=c AND stock.warehouse_id=v_warehouse AND stock.product_id=v_product;
  INSERT INTO public.stock_movements(id,product_id,warehouse_id,qty_change,
    movement_type,reference_table,reference_id,company_id,base_uom_id,
    base_uom_name_snapshot,balance_after_base_qty,actor_id,posted_at,
    movement_status,source_line_id,notes)
  SELECT v_movement,v_product,v_warehouse,v_topup,
    'PURCHASE'::public.stock_movement_type,'BACKOFFICE_INVOICE_REVISION_PREPARATION_TEST',v_batch,
    c,p.uom_id,u.name,v_stock,actor,clock_timestamp(),'POSTED',v_batch,
    'Rollback-only Invoice revision preparation fixture'
  FROM public.products p JOIN public.uoms u ON u.company_id=p.company_id AND u.id=p.uom_id
  WHERE p.company_id=c AND p.id=v_product;

  FOR v_iteration IN 2..4 LOOP
    v_phase:='save_so_'||v_iteration;
    v_created:=public.save_backoffice_sales_order_draft(NULL,NULL,gen_random_uuid(),
      jsonb_build_object('storeId',v_store,'warehouseId',v_warehouse,
        'customerId',target.customer_id,'selectedPricelistId',NULL,
        'orderDate',v_today,'plannedDeliveryDate',v_today,'isTempo',true,
        'dueDate',v_today+14,'currencyCode','IDR','globalDiscount',0,
        'deliveryFeeAmount',0,'roundingDirection','NONE','roundingIncrement',100,
        'lines',jsonb_build_array(jsonb_build_object('productUomId',v_product_uom,
          'quantity',1,'overrideUnitPrice',100000))));
    v_order:=(v_created->'data'->>'id')::uuid;
    v_phase:='confirm_so_'||v_iteration;
    v_confirmed:=public.confirm_backoffice_sales_order(v_order,
      (v_created->'data'->>'masterVersion')::bigint,gen_random_uuid());
    v_phase:='select_so_line_'||v_iteration;
    SELECT line.id INTO STRICT v_order_line FROM public.backoffice_sales_order_lines line
    WHERE line.company_id=c AND line.sales_order_id=v_order;
    v_delivery:=(v_confirmed->'fulfillment'->>'deliveryOrderId')::uuid;
    v_phase:='select_delivery_line_'||v_iteration;
    SELECT line.id INTO STRICT v_delivery_line FROM public.backoffice_sales_delivery_order_lines line
    WHERE line.company_id=c AND line.delivery_order_id=v_delivery;
    SELECT document.master_version INTO STRICT v_version FROM public.backoffice_sales_delivery_orders document
    WHERE document.company_id=c AND document.id=v_delivery;
    v_phase:='dispatch_'||v_iteration;
    PERFORM public.dispatch_backoffice_sales_delivery(v_delivery,v_version,gen_random_uuid(),
      jsonb_build_array(jsonb_build_object('deliveryLineId',v_delivery_line,'quantityUom',1)),
      'Invoice revision preparation rollback fixture');
    SELECT document.master_version INTO STRICT v_version FROM public.backoffice_sales_delivery_orders document
    WHERE document.company_id=c AND document.id=v_delivery;
    v_phase:='receive_'||v_iteration;
    v_received:=public.receive_backoffice_sales_delivery(v_delivery,v_version,gen_random_uuid(),
      v_today,'Invoice revision preparation rollback fixture');
    IF v_received->>'deliveryStatus' IS DISTINCT FROM 'COMPLETED' THEN
      RAISE EXCEPTION 'TEST_FAILED: preparation fixture delivery did not complete';
    END IF;
    v_phase:='save_invoice_'||v_iteration;
    v_invoice:=public.save_backoffice_sales_invoice_draft(NULL,NULL,gen_random_uuid(),v_order,
      jsonb_build_object('invoiceType','REGULAR','invoiceDate',v_today,'dueDate',v_today+14,
        'paymentTermId',NULL,'deliveryFeeAmount',0,
        'lines',jsonb_build_array(jsonb_build_object('salesOrderLineId',v_order_line,
          'quantityUom',1,'unitPrice',100000,'discountAmount',0,'taxApplied',false))));
    v_invoice_id:=(v_invoice->'data'->>'id')::uuid;
    v_phase:='post_invoice_'||v_iteration;
    v_posted:=public.post_backoffice_sales_invoice(v_invoice_id,
      (v_invoice->'data'->>'masterVersion')::bigint,gen_random_uuid());
    IF v_posted->'data'->>'status' IS DISTINCT FROM 'POSTED'
      OR v_posted->'finance'->>'status' IS DISTINCT FROM 'POSTED' THEN
      RAISE EXCEPTION 'TEST_FAILED: preparation fixture Invoice did not post';
    END IF;
    PERFORM set_config('mads_test.invoice_revision_fixture_'||v_iteration::text,v_invoice_id::text,true);
  END LOOP;
EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'REVISION_PREPARATION_FIXTURE_FAILED[%]: %',v_phase,SQLERRM
    USING ERRCODE=SQLSTATE;
END
$fixture$;

-- Harness supplies canonical posted taxed/untaxed invoices and final ROLLBACK.
DO $test$
DECLARE
  v_invoice public.backoffice_sales_invoices%rowtype;
  v_lines jsonb; v_bad jsonb; v_preview jsonb; v_retry jsonb;
  v_revision bigint; v_count integer:=0; v_taxed integer:=0; v_untaxed integer:=0;
  v_prior_corrections integer:=0; v_error text; v_before jsonb; v_discount numeric;
  v_date date; v_dates jsonb; v_period_id uuid; v_old_period_id uuid; v_schedule jsonb;
BEGIN
  IF has_function_privilege('authenticated',
    'private.backoffice_invoice_revision_amount_preview(uuid,uuid,bigint,bigint,jsonb)','EXECUTE')
    OR has_function_privilege('anon',
    'private.backoffice_invoice_revision_amount_preview(uuid,uuid,bigint,bigint,jsonb)','EXECUTE')
    OR has_function_privilege('service_role',
    'private.backoffice_invoice_revision_amount_preview(uuid,uuid,bigint,bigint,jsonb)','EXECUTE') THEN
    RAISE EXCEPTION 'TEST_FAILED: private candidate exposed';
  END IF;
  FOR v_invoice IN SELECT invoice.*
    FROM (VALUES
      (NULLIF(current_setting('mads_test.invoice_revision_amount_taxed',true),'')::uuid,'TAXED_PRICE_CORRECTED'::text),
      (NULLIF(current_setting('mads_test.invoice_revision_amount_untaxed',true),'')::uuid,'UNTAXED_PAID'::text)
    ) fixture(invoice_id,fixture_role)
    JOIN public.backoffice_sales_invoices invoice ON invoice.id=fixture.invoice_id
    WHERE invoice.company_id='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8'
      AND invoice.status='POSTED' AND invoice.invoice_type='REGULAR'
    ORDER BY fixture.fixture_role LOOP
    SELECT count(*) INTO v_revision FROM public.backoffice_sales_invoice_price_corrections
      WHERE company_id=v_invoice.company_id AND source_invoice_id=v_invoice.id AND status='POSTED';
    IF v_revision>0 THEN v_prior_corrections:=v_prior_corrections+1; END IF;
    SELECT jsonb_agg(jsonb_build_object('invoiceLineId',l.id,
      'unitPrice',private.backoffice_invoice_effective_entered_unit_price(l.company_id,l.id)::text,
      'discountAmount',l.discount_amount::text) ORDER BY l.id) INTO v_lines
      FROM public.backoffice_sales_invoice_lines l WHERE l.company_id=v_invoice.company_id
      AND l.invoice_id=v_invoice.id AND l.line_type='PRODUCT' AND l.source_kind='SALES_ORDER';
    IF jsonb_array_length(v_lines)<>1 THEN RAISE EXCEPTION 'TEST_PRECONDITION: one-line canonical fixture required'; END IF;
    v_preview:=private.backoffice_invoice_revision_amount_preview(v_invoice.company_id,v_invoice.id,
      v_invoice.master_version,v_revision,v_lines);
    IF (v_preview->>'changedLines')::integer<>0 OR (v_preview->>'payableDelta')::numeric<>0
      OR (v_preview->>'beforeTotal')::numeric<>(v_preview->>'afterTotal')::numeric THEN
      RAISE EXCEPTION 'TEST_FAILED: unchanged effective amount parity';
    END IF;
    v_before:=v_preview->'lines'->0->'before';
    IF (v_before->>'taxAmount')::numeric>0 THEN v_taxed:=v_taxed+1; ELSE v_untaxed:=v_untaxed+1; END IF;
    -- A late discount reduces the payable by the exact entered inclusive amount.
    v_discount:=(v_lines->0->>'discountAmount')::numeric+1000;
    v_bad:=jsonb_set(v_lines,'{0,discountAmount}',to_jsonb(v_discount::text));
    v_preview:=private.backoffice_invoice_revision_amount_preview(v_invoice.company_id,v_invoice.id,
      v_invoice.master_version,v_revision,v_bad);
    v_retry:=private.backoffice_invoice_revision_amount_preview(v_invoice.company_id,v_invoice.id,
      v_invoice.master_version,v_revision,v_bad);
    IF v_preview IS DISTINCT FROM v_retry OR (v_preview->>'payableDelta')::numeric<>-1000
      OR (v_preview->>'salesDiscountDelta')::numeric<>1000 OR (v_preview->>'changedLines')::integer<>1
      OR (v_preview->>'grossRevenueDelta')::numeric-(v_preview->>'salesDiscountDelta')::numeric
         +(v_preview->>'taxDelta')::numeric<>(v_preview->>'payableDelta')::numeric THEN
      RAISE EXCEPTION 'TEST_FAILED: late discount arithmetic / deterministic preview';
    END IF;
    -- Increase price and discount together; neither change may be lost.
    v_bad:=jsonb_set(v_bad,'{0,unitPrice}',to_jsonb(((v_lines->0->>'unitPrice')::numeric+2000)::text));
    v_preview:=private.backoffice_invoice_revision_amount_preview(v_invoice.company_id,v_invoice.id,
      v_invoice.master_version,v_revision,v_bad);
    IF (v_preview->>'payableDelta')::numeric<>
      (v_preview->'lines'->0->>'quantityUom')::numeric*2000-1000 THEN
      RAISE EXCEPTION 'TEST_FAILED: joint price discount change';
    END IF;
    -- Zero net delta is legitimate for metadata-only correction planning.
    v_bad:=jsonb_set(v_bad,'{0,discountAmount}',to_jsonb(round((v_lines->0->>'discountAmount')::numeric+
      (v_preview->'lines'->0->>'quantityUom')::numeric*2000,4)::text));
    v_preview:=private.backoffice_invoice_revision_amount_preview(v_invoice.company_id,v_invoice.id,
      v_invoice.master_version,v_revision,v_bad);
    IF (v_preview->>'payableDelta')::numeric<>0 OR (v_preview->>'changedLines')::integer<>1 THEN
      RAISE EXCEPTION 'TEST_FAILED: zero net change must preserve changed line';
    END IF;
    FOR v_bad,v_error IN SELECT * FROM (VALUES
      (jsonb_set(v_lines,'{0,unitPrice}','null'::jsonb),'INVOICE_REVISION_LINE_INVALID'),
      (jsonb_set(v_lines,'{0,unitPrice}','"NaN"'::jsonb),'INVOICE_REVISION_LINE_INVALID'),
      (jsonb_set(v_lines,'{0,unitPrice}','"-1"'::jsonb),'INVOICE_REVISION_LINE_INVALID'),
      (jsonb_set(v_lines,'{0,unitPrice}','"1.00001"'::jsonb),'INVOICE_REVISION_LINE_INVALID'),
      (jsonb_set(v_lines,'{0,quantity}','"9"'::jsonb),'INVOICE_REVISION_LINE_INVALID'),
      (jsonb_set(v_lines,'{0,invoiceLineId}',to_jsonb(gen_random_uuid()::text)),'INVOICE_REVISION_LINE_OWNERSHIP_INVALID'),
      (jsonb_set(v_lines,'{0,discountAmount}','"999999999"'::jsonb),'INVOICE_DISCOUNT_EXCEEDS_CORRECTED_LINE_TOTAL'),
      (v_lines||v_lines,'INVOICE_REVISION_LINE_SET_MISMATCH'),
      ('[]'::jsonb,'INVOICE_REVISION_PREVIEW_PAYLOAD_INVALID'),
      ('null'::jsonb,'INVOICE_REVISION_PREVIEW_PAYLOAD_INVALID')
    ) t(payload,expected) LOOP
      BEGIN
        PERFORM private.backoffice_invoice_revision_amount_preview(v_invoice.company_id,v_invoice.id,
          v_invoice.master_version,v_revision,v_bad);
        RAISE EXCEPTION 'TEST_FAILED: invalid preview accepted';
      EXCEPTION WHEN raise_exception THEN IF SQLERRM<>v_error THEN RAISE; END IF; END;
    END LOOP;
    BEGIN
      PERFORM private.backoffice_invoice_revision_amount_preview(v_invoice.company_id,v_invoice.id,
        v_invoice.master_version+1,v_revision,v_lines);
      RAISE EXCEPTION 'TEST_FAILED: stale master accepted';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'MASTER_VERSION_CONFLICT' THEN RAISE; END IF; END;
    BEGIN
      PERFORM private.backoffice_invoice_revision_amount_preview(v_invoice.company_id,v_invoice.id,
        v_invoice.master_version,v_revision+1,v_lines);
      RAISE EXCEPTION 'TEST_FAILED: stale revision accepted';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVOICE_PRICE_REVISION_CONFLICT' THEN RAISE; END IF; END;
    BEGIN
      PERFORM private.backoffice_invoice_revision_amount_preview('07bdffb9-8c56-444c-a49b-81ac86745674',
        v_invoice.id,v_invoice.master_version,v_revision,v_lines);
      RAISE EXCEPTION 'TEST_FAILED: foreign tenant source accepted';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'BACKOFFICE_SALES_INVOICE_NOT_FOUND' THEN RAISE; END IF; END;
    v_date:=(date_trunc('month',v_invoice.invoice_date)+interval '1 month')::date;
    -- Each synthetic invoice uses this month's newly-created open period.
    SELECT id INTO STRICT v_old_period_id FROM public.accounting_periods
      WHERE company_id=v_invoice.company_id AND v_invoice.invoice_date BETWEEN start_date AND end_date;
    SELECT id INTO v_period_id FROM public.accounting_periods
      WHERE company_id=v_invoice.company_id AND v_date BETWEEN start_date AND end_date;
    IF v_period_id IS NULL THEN
      BEGIN
        PERFORM private.backoffice_invoice_revision_date_preview(v_invoice.company_id,v_invoice.id,
          v_invoice.master_version,v_date);
        RAISE EXCEPTION 'TEST_FAILED: missing period accepted';
      EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVOICE_REVISION_ACCOUNTING_PERIOD_MISSING' THEN RAISE; END IF; END;
      INSERT INTO public.accounting_periods(company_id,period_year,period_month,start_date,end_date,
        status,created_by,updated_by) VALUES(v_invoice.company_id,extract(year FROM v_date)::integer,
        extract(month FROM v_date)::integer,v_date,(v_date+interval '1 month -1 day')::date,
        'OPEN',v_invoice.created_by,v_invoice.created_by) RETURNING id INTO v_period_id;
    END IF;
    v_dates:=private.backoffice_invoice_revision_date_preview(v_invoice.company_id,v_invoice.id,
      v_invoice.master_version,v_date);
    IF (v_dates->>'dateChanged')::boolean IS DISTINCT FROM true
      OR v_dates->>'previousPeriodId'=v_dates->>'periodId'
      OR jsonb_array_length(v_dates->'schedules')=0 THEN
      RAISE EXCEPTION 'TEST_FAILED: cross-month nonzero schedules required';
    END IF;
    FOR v_schedule IN SELECT value FROM jsonb_array_elements(v_dates->'schedules') LOOP
      IF (v_schedule->>'dueDate')::date-v_date<>
        (v_schedule->>'previousDueDate')::date-v_invoice.invoice_date THEN
        RAISE EXCEPTION 'TEST_FAILED: installment term changed';
      END IF;
    END LOOP;
    BEGIN
      UPDATE public.accounting_periods SET status='LOCKED',closed_by=v_invoice.created_by,
        closed_at=clock_timestamp() WHERE id=v_period_id;
      PERFORM private.backoffice_invoice_revision_date_preview(v_invoice.company_id,v_invoice.id,
        v_invoice.master_version,v_date);
      RAISE EXCEPTION 'TEST_FAILED: locked destination period accepted';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVOICE_REVISION_ACCOUNTING_PERIOD_LOCKED' THEN RAISE; END IF; END;
    BEGIN
      UPDATE public.accounting_periods SET status='LOCKED',closed_by=v_invoice.created_by,
        closed_at=clock_timestamp() WHERE id=v_old_period_id;
      PERFORM private.backoffice_invoice_revision_date_preview(v_invoice.company_id,v_invoice.id,
        v_invoice.master_version,v_date);
      RAISE EXCEPTION 'TEST_FAILED: locked source period accepted';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVOICE_REVISION_ACCOUNTING_PERIOD_LOCKED' THEN RAISE; END IF; END;
    v_count:=v_count+1;
  END LOOP;
  IF v_count<2 OR v_taxed<1 OR v_untaxed<1 OR v_prior_corrections<1 THEN
    RAISE EXCEPTION 'TEST_PRECONDITION: nonzero taxed untaxed previously-corrected sources required';
  END IF;
END
$test$;
SELECT 'backoffice_invoice_revision_amount_preview_behavior' check_name,'PASS' status,0 violation_rows,
  jsonb_build_object('tested',ARRAY['canonical taxed and untaxed posted fixtures',
    'existing effective price correction parity','late discount exact payable delta',
    'joint price and discount changes','zero-net financial change',
    'invalid NULL NaN precision quantity foreign-line payloads rejected',
    'stale master and price revisions rejected','cross-tenant ownership rejected',
    'deterministic read-only preview','no browser or service-role execute grant',
    'cross-month KEEP_TERM schedule date preview','missing or locked source/destination period rejected']) details;

-- Uses four canonical taxed invoices created by the unmodified posting suite.
-- NO effective customer transfer or accounting relocation is claimed here.
DO $test$
DECLARE
  c uuid:='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8';actor uuid:=auth.uid();
  ids uuid[]; target public.backoffice_sales_invoices%rowtype;customer_new uuid:=gen_random_uuid();
  method uuid;allocations jsonb;receipt jsonb;posted jsonb;receipt_four uuid;receipt_two uuid;
  command jsonb;result jsonb;retry jsonb;operation uuid:=gen_random_uuid();snapshot jsonb;lines jsonb;
  revision bigint;before_data jsonb:='{}';after_data jsonb:='{}';t record;fingerprint text;part jsonb;
  bad jsonb;expected text;draft jsonb;
  phase text:='behavior_start';
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'TEST_PRECONDITION: auth context required'; END IF;
  phase:='load_fixture_ids';
  ids:=ARRAY[
    NULLIF(current_setting('mads_test.invoice_revision_fixture_1',true),'')::uuid,
    NULLIF(current_setting('mads_test.invoice_revision_fixture_2',true),'')::uuid,
    NULLIF(current_setting('mads_test.invoice_revision_fixture_3',true),'')::uuid,
    NULLIF(current_setting('mads_test.invoice_revision_fixture_4',true),'')::uuid
  ];
  IF cardinality(ids)<>4 THEN RAISE EXCEPTION 'TEST_PRECONDITION: exact four-invoice fixture required'; END IF;
  phase:='load_target_invoice';
  SELECT * INTO STRICT target FROM public.backoffice_sales_invoices WHERE company_id=c AND id=ids[1];
  IF NOT EXISTS(SELECT 1 FROM public.backoffice_sales_down_payment_applications a
      WHERE a.company_id=c AND a.regular_invoice_id=target.id AND a.status='POSTED') THEN
    RAISE EXCEPTION 'TEST_PRECONDITION: target nonzero applied DP required'; END IF;
  IF (SELECT count(DISTINCT customer_id) FROM public.backoffice_sales_invoices WHERE company_id=c AND id=ANY(ids))<>1 THEN
    RAISE EXCEPTION 'TEST_PRECONDITION: shared customer required'; END IF;
  phase:='load_payment_method';
  SELECT payment_method_id INTO STRICT method FROM public.customer_receipt_documents
    WHERE company_id=c AND status='POSTED' ORDER BY id LIMIT 1;
  INSERT INTO public.customers(id,company_id,code,name,customer_category_id,customer_type,is_active,
    is_system_customer,current_balance,credit_limit,created_by,updated_by)
    SELECT customer_new,c,'STAGING-REVISION-CUSTOMER','STAGING TEST Revised Billing',customer_category_id,
      customer_type,true,false,0,0,actor,actor FROM public.customers WHERE company_id=c AND id=target.customer_id;
  SELECT jsonb_agg(jsonb_build_object('sourceType','BACKOFFICE_SALES_INVOICE','sourceId',id,
    'clientAllocationKey',gen_random_uuid(),'allocatedAmount',1000) ORDER BY id) INTO allocations FROM unnest(ids) id;
  phase:='save_shared_four_receipt';
  receipt:=public.save_customer_receipt_allocated_draft(NULL,NULL,target.customer_id,current_date,
    method,'STAGING-SHARED-FOUR',NULL,'Shared four invoice fixture',4000,allocations);
  receipt_four:=(receipt->>'documentId')::uuid;
  phase:='post_shared_four_receipt';
  posted:=public.post_customer_receipt_unified(receipt_four,(receipt->>'masterVersion')::bigint,gen_random_uuid());
  IF posted->>'status' IS DISTINCT FROM 'POSTED' THEN RAISE EXCEPTION 'TEST_FAILED: shared receipt four not posted'; END IF;
  SELECT jsonb_agg(jsonb_build_object('sourceType','BACKOFFICE_SALES_INVOICE','sourceId',id,
    'clientAllocationKey',gen_random_uuid(),'allocatedAmount',100) ORDER BY id) INTO allocations FROM unnest(ids[1:2]) id;
  phase:='save_shared_two_receipt';
  receipt:=public.save_customer_receipt_allocated_draft(NULL,NULL,target.customer_id,current_date,
    method,'STAGING-SHARED-TWO',NULL,'Shared two invoice fixture',200,allocations);
  receipt_two:=(receipt->>'documentId')::uuid;
  phase:='post_shared_two_receipt';
  posted:=public.post_customer_receipt_unified(receipt_two,(receipt->>'masterVersion')::bigint,gen_random_uuid());
  IF posted->>'status' IS DISTINCT FROM 'POSTED' THEN RAISE EXCEPTION 'TEST_FAILED: shared receipt two not posted'; END IF;
  phase:='save_pending_receipt';
  draft:=public.save_customer_receipt_allocated_draft(NULL,NULL,target.customer_id,current_date,
    method,'STAGING-PENDING',NULL,'Pending dependency fixture',50,
    jsonb_build_array(jsonb_build_object('sourceType','BACKOFFICE_SALES_INVOICE','sourceId',target.id,
      'clientAllocationKey',gen_random_uuid(),'allocatedAmount',50)));
  -- Read again: existing payment writers may update the schedule/header version.
  SELECT * INTO STRICT target FROM public.backoffice_sales_invoices WHERE company_id=c AND id=ids[1];
  SELECT count(*) INTO revision FROM public.backoffice_sales_invoice_price_corrections
    WHERE company_id=c AND source_invoice_id=target.id AND status='POSTED';
  SELECT jsonb_agg(jsonb_build_object('invoiceLineId',l.id,
    'unitPrice',private.backoffice_invoice_effective_entered_unit_price(c,l.id)::text,
    'discountAmount',l.discount_amount::text) ORDER BY l.id) INTO lines
    FROM public.backoffice_sales_invoice_lines l WHERE l.company_id=c AND l.invoice_id=target.id
      AND l.line_type='PRODUCT' AND l.source_kind='SALES_ORDER';
  command:=jsonb_build_object('kind','INVOICE_REVISION','invoiceId',target.id,'operationId',operation,
    'masterVersion',target.master_version,'revision',revision,'customerId',customer_new,
    'invoiceDate',target.invoice_date,'dueDate',jsonb_build_object('mode','KEEP_TERM'),'lines',lines);
  FOR t IN SELECT n.nspname s,cl.relname r FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace
    WHERE cl.relkind='r' AND (n.nspname IN('public','private') OR (n.nspname='auth' AND cl.relname='users'))
      AND NOT(n.nspname='private' AND cl.relname='backoffice_invoice_revision_preparations') ORDER BY 1,2 LOOP
    EXECUTE format('SELECT md5(COALESCE(string_agg(h,'''' ORDER BY h),'''')) FROM (SELECT md5(to_jsonb(x)::text) h FROM %I.%I x) q',t.s,t.r) INTO fingerprint;
    before_data:=before_data||jsonb_build_object(t.s||'.'||t.r,fingerprint);
  END LOOP;
  phase:='prepare_revision';
  result:=private.prepare_backoffice_invoice_revision(command);
  retry:=private.prepare_backoffice_invoice_revision(command);
  IF result->>'status' IS DISTINCT FROM 'PREPARED_NOT_POSTED' OR retry->>'exactRetry' IS DISTINCT FROM 'true'
    OR result-'exactRetry' IS DISTINCT FROM retry-'exactRetry'
    OR (SELECT count(*) FROM private.backoffice_invoice_revision_preparations WHERE company_id=c AND operation_id=operation)<>1 THEN
    RAISE EXCEPTION 'TEST_FAILED: preparation exact retry'; END IF;
  SELECT source_snapshot INTO STRICT snapshot FROM private.backoffice_invoice_revision_preparations
    WHERE company_id=c AND operation_id=operation AND actor_id=actor AND created_at<=clock_timestamp();
  SELECT value INTO STRICT part FROM jsonb_array_elements(snapshot->'receipts')
    WHERE value->'document'->>'id'=receipt_four::text;
  IF jsonb_array_length(part->'targetAllocations')<>1 OR jsonb_array_length(part->'otherBackofficeAllocations')<>3
    OR (part->'targetAllocations'->0->>'allocated_amount')::numeric<>1000
    OR (SELECT sum((value->>'allocated_amount')::numeric) FROM jsonb_array_elements(part->'otherBackofficeAllocations'))<>3000 THEN
    RAISE EXCEPTION 'TEST_FAILED: four-way shared receipt ownership'; END IF;
  SELECT value INTO STRICT part FROM jsonb_array_elements(snapshot->'receipts')
    WHERE value->'document'->>'id'=receipt_two::text;
  IF jsonb_array_length(part->'targetAllocations')<>1 OR jsonb_array_length(part->'otherBackofficeAllocations')<>1
    OR (part->'targetAllocations'->0->>'allocated_amount')::numeric<>100 THEN
    RAISE EXCEPTION 'TEST_FAILED: two-way shared receipt ownership'; END IF;
  IF jsonb_array_length(snapshot->'downPayments')<1
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'downPayments') dp,
      jsonb_array_elements(dp->'applications') a WHERE a->>'regular_invoice_id'=target.id::text AND a->>'status'='POSTED')
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'receipts') r WHERE r->'document'->>'status'='DRAFT') THEN
    RAISE EXCEPTION 'TEST_FAILED: applied DP and pending Receipt must be retained'; END IF;
  PERFORM private.assert_backoffice_invoice_revision_preparation_fresh(operation);
  FOR bad,expected IN SELECT * FROM (VALUES
    (command||jsonb_build_object('notes','different payload'),'IDEMPOTENCY_PAYLOAD_CONFLICT'),
    (command||jsonb_build_object('companyId',c),'INVOICE_REVISION_COMMAND_INVALID'),
    (command||jsonb_build_object('operationId',gen_random_uuid(),'customerId',gen_random_uuid()),'INVOICE_REVISION_CUSTOMER_INVALID'),
    (command||jsonb_build_object('operationId',gen_random_uuid(),'masterVersion',target.master_version+1),'MASTER_VERSION_CONFLICT')
  ) cases(payload,error) LOOP
    BEGIN PERFORM private.prepare_backoffice_invoice_revision(bad);RAISE EXCEPTION 'TEST_FAILED: invalid preparation accepted';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM<>expected THEN RAISE; END IF; END;
  END LOOP;
  BEGIN
    UPDATE public.customers SET name='STAGING TEST changed billing master',master_version=master_version+1 WHERE id=customer_new;
    PERFORM private.assert_backoffice_invoice_revision_preparation_fresh(operation);
    RAISE EXCEPTION 'TEST_FAILED: Customer drift accepted';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVOICE_REVISION_DEPENDENCIES_CHANGED' THEN RAISE; END IF; END;
  BEGIN
    PERFORM public.save_customer_receipt_allocated_draft((draft->>'documentId')::uuid,(draft->>'masterVersion')::bigint,
      target.customer_id,current_date,method,'STAGING-PENDING-EDITED',NULL,'changed dependency',50,
      jsonb_build_array(jsonb_build_object('sourceType','BACKOFFICE_SALES_INVOICE','sourceId',target.id,
        'clientAllocationKey',gen_random_uuid(),'allocatedAmount',50)));
    PERFORM private.assert_backoffice_invoice_revision_preparation_fresh(operation);
    RAISE EXCEPTION 'TEST_FAILED: Receipt drift accepted';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVOICE_REVISION_DEPENDENCIES_CHANGED' THEN RAISE; END IF; END;
  BEGIN
    UPDATE private.backoffice_invoice_revision_preparations SET request_snapshot='{}' WHERE company_id=c AND operation_id=operation;
    RAISE EXCEPTION 'TEST_FAILED: history update allowed';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVOICE_REVISION_PREPARATION_IMMUTABLE' THEN RAISE; END IF; END;
  BEGIN
    DELETE FROM private.backoffice_invoice_revision_preparations WHERE company_id=c AND operation_id=operation;
    RAISE EXCEPTION 'TEST_FAILED: history delete allowed';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVOICE_REVISION_PREPARATION_IMMUTABLE' THEN RAISE; END IF; END;
  BEGIN
    PERFORM set_config('request.jwt.claim.sub','',true);
    PERFORM set_config('request.jwt.claims','{}',true);
    PERFORM private.prepare_backoffice_invoice_revision(command);
    RAISE EXCEPTION 'TEST_FAILED: unauthenticated retry accepted';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'AUTHENTICATION_REQUIRED' THEN RAISE; END IF; END;
  IF auth.uid() IS DISTINCT FROM actor THEN RAISE EXCEPTION 'TEST_FAILED: auth subtransaction restore'; END IF;
  FOR t IN SELECT n.nspname s,cl.relname r FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace
    WHERE cl.relkind='r' AND (n.nspname IN('public','private') OR (n.nspname='auth' AND cl.relname='users'))
      AND NOT(n.nspname='private' AND cl.relname='backoffice_invoice_revision_preparations') ORDER BY 1,2 LOOP
    EXECUTE format('SELECT md5(COALESCE(string_agg(h,'''' ORDER BY h),'''')) FROM (SELECT md5(to_jsonb(x)::text) h FROM %I.%I x) q',t.s,t.r) INTO fingerprint;
    after_data:=after_data||jsonb_build_object(t.s||'.'||t.r,fingerprint);
  END LOOP;
  IF before_data IS DISTINCT FROM after_data THEN RAISE EXCEPTION 'TEST_FAILED: preparation changed existing business rows'; END IF;
  IF has_function_privilege('authenticated','private.prepare_backoffice_invoice_revision(jsonb)','EXECUTE')
    OR has_table_privilege('authenticated','private.backoffice_invoice_revision_preparations','INSERT') THEN
    RAISE EXCEPTION 'TEST_FAILED: candidate publicly writable'; END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'REVISION_PREPARATION_BEHAVIOR_FAILED[%]: %',phase,SQLERRM
    USING ERRCODE=SQLSTATE;
END
$test$;
SELECT 'backoffice_invoice_revision_preparation_behavior' check_name,'PASS' status,0 violation_rows,
  jsonb_build_object('tested',ARRAY['immutable prepared operation, not posting','server-owned actor and Company',
    'posted shared Receipts with four and two invoices','only target allocation selected; all siblings retained',
    'nonzero applied DP and draft Receipt dependencies','exact retry and changed-payload conflict',
    'Customer and Receipt drift rejected','history update/delete rejected','unauthenticated retry rejected',
    'existing business-row fingerprints unchanged during preparation','outer transaction rolled back']) details;

DO $test$
DECLARE
  c uuid:='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8';target public.backoffice_sales_invoices%rowtype;
  ids uuid[];customer_new uuid;lines jsonb;revision bigint;operation uuid:=gen_random_uuid();
  command jsonb;prepared jsonb;plan jsonb;before_data jsonb:='{}';after_data jsonb:='{}';
  t record;fingerprint text;
BEGIN
  ids:=ARRAY[
    NULLIF(current_setting('mads_test.invoice_revision_fixture_1',true),'')::uuid,
    NULLIF(current_setting('mads_test.invoice_revision_fixture_2',true),'')::uuid,
    NULLIF(current_setting('mads_test.invoice_revision_fixture_3',true),'')::uuid,
    NULLIF(current_setting('mads_test.invoice_revision_fixture_4',true),'')::uuid
  ];
  SELECT * INTO STRICT target FROM public.backoffice_sales_invoices WHERE company_id=c AND id=ids[1];
  SELECT id INTO STRICT customer_new FROM public.customers
    WHERE company_id=c AND code='STAGING-REVISION-CUSTOMER';
  SELECT count(*) INTO revision FROM public.backoffice_sales_invoice_price_corrections
    WHERE company_id=c AND source_invoice_id=target.id AND status='POSTED';
  SELECT jsonb_agg(jsonb_build_object('invoiceLineId',l.id,
    'unitPrice',private.backoffice_invoice_effective_entered_unit_price(c,l.id)::text,
    'discountAmount',l.discount_amount::text) ORDER BY l.id) INTO lines
  FROM public.backoffice_sales_invoice_lines l WHERE l.company_id=c AND l.invoice_id=target.id
    AND l.line_type='PRODUCT' AND l.source_kind='SALES_ORDER';
  command:=jsonb_build_object('kind','INVOICE_REVISION','invoiceId',target.id,
    'operationId',operation,'masterVersion',target.master_version,'revision',revision,
    'customerId',customer_new,'invoiceDate',target.invoice_date+1,
    'dueDate',jsonb_build_object('mode','KEEP_TERM'),'lines',lines);
  FOR t IN SELECT n.nspname s,cl.relname r FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace
    WHERE cl.relkind='r' AND (n.nspname IN('public','private') OR (n.nspname='auth' AND cl.relname='users'))
      AND NOT(n.nspname='private' AND cl.relname='backoffice_invoice_revision_preparations') ORDER BY 1,2 LOOP
    EXECUTE format('SELECT md5(COALESCE(string_agg(h,'''' ORDER BY h),'''')) FROM (SELECT md5(to_jsonb(x)::text) h FROM %I.%I x) q',t.s,t.r) INTO fingerprint;
    before_data:=before_data||jsonb_build_object(t.s||'.'||t.r,fingerprint);
  END LOOP;
  prepared:=private.prepare_backoffice_invoice_revision(command);
  plan:=private.plan_backoffice_invoice_revision_execution(operation);
  IF plan->>'status' IS DISTINCT FROM 'EXECUTION_PLAN_NOT_POSTED'
    OR (plan->>'requiresAtomicWriter')::boolean IS DISTINCT FROM true
    OR (plan->>'stockEffect')::boolean IS DISTINCT FROM false
    OR jsonb_array_length(plan->'receipts')<>3
    OR (plan->>'postedReceiptAmount')::numeric<>1100
    OR (plan->>'receiptAdvanceAmount')::numeric<>1100
    OR (plan->>'draftReceiptAmount')::numeric<>50
    OR jsonb_array_length(plan->'downPayments')<1
    OR (plan->>'postedDownPaymentAmount')::numeric<=0
    OR (plan->'journal'->>'requiresRelocation')::boolean IS DISTINCT FROM true
    OR (plan->'journal'->>'lineCount')::integer<2 THEN
    RAISE EXCEPTION 'TEST_FAILED: exact execution plan mismatch: %',plan;
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(plan->'receipts') r
      WHERE r->>'action'='TRANSFER_TO_ADVANCE_THEN_APPLY')<>2
    OR (SELECT count(*) FROM jsonb_array_elements(plan->'receipts') r
      WHERE r->>'action'='REWRITE_DRAFT_TARGET_SHARE')<>1
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'receipts') r
      WHERE (r->>'otherBackofficeAllocationCount')::integer=3) THEN
    RAISE EXCEPTION 'TEST_FAILED: selected Receipt share plan mismatch';
  END IF;
  FOR t IN SELECT n.nspname s,cl.relname r FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace
    WHERE cl.relkind='r' AND (n.nspname IN('public','private') OR (n.nspname='auth' AND cl.relname='users'))
      AND NOT(n.nspname='private' AND cl.relname='backoffice_invoice_revision_preparations') ORDER BY 1,2 LOOP
    EXECUTE format('SELECT md5(COALESCE(string_agg(h,'''' ORDER BY h),'''')) FROM (SELECT md5(to_jsonb(x)::text) h FROM %I.%I x) q',t.s,t.r) INTO fingerprint;
    after_data:=after_data||jsonb_build_object(t.s||'.'||t.r,fingerprint);
  END LOOP;
  IF before_data IS DISTINCT FROM after_data THEN RAISE EXCEPTION 'TEST_FAILED: execution plan changed business rows'; END IF;
END
$test$;
SELECT 'backoffice_invoice_revision_execution_plan_behavior' check_name,'PASS' status,0 violation_rows,
  jsonb_build_object('tested',ARRAY['Receipt to Invoice lock order','four/two shared Receipt selected shares',
    'posted Receipt before revised Invoice becomes advance','Draft Receipt rewrite plan','posted DP transfer plan',
    'source Journal and open-period relocation plan','no Stock FIFO SO DO or business-row mutation',
    'outer transaction rolled back']) details;

DO $test$
DECLARE operation uuid;plan jsonb;leg jsonb;debit numeric;credit numeric;
BEGIN
  SELECT operation_id INTO STRICT operation
  FROM private.backoffice_invoice_revision_preparations
  WHERE (request_snapshot->>'invoiceDate')::date>
    (source_snapshot->'invoice'->>'invoice_date')::date
  ORDER BY created_at DESC LIMIT 1;
  plan:=private.plan_backoffice_invoice_revision_journals(operation);
  IF plan->>'status' IS DISTINCT FROM 'JOURNAL_PLAN_NOT_POSTED'
    OR (plan->>'writerEffect')::boolean IS DISTINCT FROM false
    OR jsonb_array_length(plan->'recognitionReversal'->'lines')<2
    OR jsonb_array_length(plan->'recognitionReplacement'->'lines')<2
    OR jsonb_array_length(plan->'receiptJournalLegs')<>4
    OR jsonb_array_length(plan->'downPaymentJournalLegs')<1
    OR jsonb_array_length(plan->'amountJournal'->'lines')<>0 THEN
    RAISE EXCEPTION 'TEST_FAILED: journal plan shape mismatch: %',plan;
  END IF;
  FOR leg IN SELECT value FROM jsonb_array_elements(jsonb_build_array(
      plan->'recognitionReversal',plan->'recognitionReplacement')
      ||plan->'receiptJournalLegs'||plan->'downPaymentJournalLegs'
      ||jsonb_build_array(plan->'amountJournal')) LOOP
    SELECT round(COALESCE(sum((line->>'debit')::numeric),0),4),
      round(COALESCE(sum((line->>'credit')::numeric),0),4)
    INTO debit,credit FROM jsonb_array_elements(leg->'lines') line;
    IF debit<>credit THEN RAISE EXCEPTION 'TEST_FAILED: journal plan leg unbalanced'; END IF;
  END LOOP;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'receiptJournalLegs') item(value)
      WHERE item.value->>'leg'='RECEIPT_TO_ADVANCE')
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'receiptJournalLegs') item(value)
      WHERE item.value->>'leg'='ADVANCE_TO_REVISED_INVOICE')
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'downPaymentJournalLegs') item(value)
      WHERE item.value->>'leg'='TRANSFER_DP_ATTRIBUTION') THEN
    RAISE EXCEPTION 'TEST_FAILED: mandatory settlement legs missing';
  END IF;
END
$test$;
SELECT 'backoffice_invoice_revision_journal_plan_behavior' check_name,'PASS' status,0 violation_rows,
  jsonb_build_object('tested',ARRAY['source recognition reversal balanced',
    'replacement recognition uses revised customer and date','posted Receipt converts to advance then reapplies',
    'posted DP attribution transfer','every journal leg independently balanced','no writer effect',
    'outer transaction rolled back']) details;

DO $test$
DECLARE
  c uuid:='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8';operation uuid;target_invoice_id uuid;
  source_invoice jsonb;source_lines jsonb;source_receipts jsonb;source_dp jsonb;source_journal jsonb;
  result jsonb;retry jsonb;effective jsonb;plan jsonb;target_revision_id uuid;journal_count integer;
  schedule_due date;expected_due date;
  amount_operation uuid:=gen_random_uuid();amount_invoice public.backoffice_sales_invoices%rowtype;
  amount_line uuid;amount_lines jsonb;amount_command jsonb;amount_prepared jsonb;amount_result jsonb;
  amount_revision bigint;amount_effective jsonb;
  repeat_operation uuid:=gen_random_uuid();repeat_command jsonb;repeat_prepared jsonb;repeat_result jsonb;
  report_operation uuid:=gen_random_uuid();report_invoice public.backoffice_sales_invoices%rowtype;
  report_lines jsonb;report_command jsonb;report_result jsonb;report_customer uuid;report_revision bigint;
BEGIN
  SELECT p.operation_id,p.invoice_id INTO STRICT operation,target_invoice_id
  FROM private.backoffice_invoice_revision_preparations p
  WHERE (p.request_snapshot->>'invoiceDate')::date>
    (p.source_snapshot->'invoice'->>'invoice_date')::date
  ORDER BY p.created_at DESC LIMIT 1;
  plan:=private.plan_backoffice_invoice_revision_journals(operation);
  SELECT to_jsonb(i) INTO STRICT source_invoice FROM public.backoffice_sales_invoices i
    WHERE i.company_id=c AND i.id=target_invoice_id;
  SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) INTO source_lines
    FROM public.backoffice_sales_invoice_lines l WHERE l.company_id=c AND l.invoice_id=target_invoice_id;
  SELECT jsonb_agg(to_jsonb(x) ORDER BY x.kind,x.id) INTO source_receipts FROM (
    SELECT 'document' kind,d.id,to_jsonb(d) body FROM public.customer_receipt_documents d
      WHERE d.company_id=c AND EXISTS(SELECT 1 FROM public.customer_receipt_backoffice_invoice_allocations a
        WHERE a.company_id=c AND a.document_id=d.id AND a.invoice_id=target_invoice_id)
    UNION ALL
    SELECT 'allocation',a.id,to_jsonb(a) FROM public.customer_receipt_backoffice_invoice_allocations a
      WHERE a.company_id=c AND a.invoice_id=target_invoice_id) x;
  SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) INTO source_dp
    FROM public.backoffice_sales_down_payment_applications a
    WHERE a.company_id=c AND a.regular_invoice_id=target_invoice_id;
  SELECT to_jsonb(j) INTO STRICT source_journal FROM public.finance_journals j
    WHERE j.company_id=c AND j.id=(plan->'recognitionReversal'->>'sourceJournalId')::uuid;
  expected_due:=(plan->'dates'->'schedules'->0->>'dueDate')::date;

  result:=private.execute_backoffice_invoice_revision(operation);
  SET CONSTRAINTS ALL IMMEDIATE;
  SET CONSTRAINTS ALL DEFERRED;
  retry:=private.execute_backoffice_invoice_revision(operation);
  target_revision_id:=(result->>'revisionId')::uuid;
  IF result->>'status' IS DISTINCT FROM 'POSTED' OR result->>'exactRetry' IS DISTINCT FROM 'false'
    OR retry->>'exactRetry' IS DISTINCT FROM 'true'
    OR result-'exactRetry' IS DISTINCT FROM retry-'exactRetry' THEN
    RAISE EXCEPTION 'TEST_FAILED: writer response or exact retry mismatch';
  END IF;
  IF (SELECT count(*) FROM private.backoffice_invoice_revisions r
      WHERE r.company_id=c AND r.id=target_revision_id AND r.invoice_id=target_invoice_id)<>1
    OR (SELECT count(*) FROM private.backoffice_invoice_revision_lines l
      WHERE l.company_id=c AND l.revision_id=target_revision_id)<>jsonb_array_length(plan->'amounts'->'lines')
    OR (SELECT count(*) FROM private.backoffice_invoice_revision_settlement_attributions a
      WHERE a.company_id=c AND a.revision_id=target_revision_id)<4 THEN
    RAISE EXCEPTION 'TEST_FAILED: immutable revision lineage incomplete';
  END IF;
  SELECT count(*) INTO journal_count FROM public.finance_journals j
    WHERE j.company_id=c AND j.source_type='backoffice_invoice_revisions' AND j.source_id=target_revision_id;
  IF journal_count<>jsonb_array_length(result->'journalIds') OR journal_count<7
    OR EXISTS(SELECT 1 FROM public.finance_journals j WHERE j.company_id=c
      AND j.source_type='backoffice_invoice_revisions' AND j.source_id=target_revision_id
      AND (j.status<>'POSTED' OR j.total_debit<=0 OR j.total_debit<>j.total_credit)) THEN
    RAISE EXCEPTION 'TEST_FAILED: posted correction journal contract';
  END IF;
  effective:=private.backoffice_invoice_effective_identity(c,target_invoice_id,NULL);
  IF effective->>'customerId' IS DISTINCT FROM result->>'customerId'
    OR effective->>'invoiceDate' IS DISTINCT FROM result->>'invoiceDate'
    OR (effective->>'revision')::bigint<>1 THEN
    RAISE EXCEPTION 'TEST_FAILED: effective identity mismatch';
  END IF;
  SELECT due_date INTO STRICT schedule_due FROM public.backoffice_sales_invoice_receivable_schedules
    WHERE company_id=c AND invoice_id=target_invoice_id ORDER BY installment_no LIMIT 1;
  IF schedule_due IS DISTINCT FROM expected_due THEN RAISE EXCEPTION 'TEST_FAILED: schedule date not shifted'; END IF;
  IF (SELECT to_jsonb(i) FROM public.backoffice_sales_invoices i WHERE i.company_id=c AND i.id=target_invoice_id)
      IS DISTINCT FROM source_invoice
    OR (SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM public.backoffice_sales_invoice_lines l
      WHERE l.company_id=c AND l.invoice_id=target_invoice_id) IS DISTINCT FROM source_lines
    OR (SELECT to_jsonb(j) FROM public.finance_journals j
      WHERE j.company_id=c AND j.id=(plan->'recognitionReversal'->>'sourceJournalId')::uuid)
      IS DISTINCT FROM source_journal THEN
    RAISE EXCEPTION 'TEST_FAILED: posted source Invoice, lines or Journal mutated';
  END IF;
  IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY x.kind,x.id) FROM (
      SELECT 'document' kind,d.id,to_jsonb(d) body FROM public.customer_receipt_documents d
        WHERE d.company_id=c AND EXISTS(SELECT 1 FROM public.customer_receipt_backoffice_invoice_allocations a
          WHERE a.company_id=c AND a.document_id=d.id AND a.invoice_id=target_invoice_id)
      UNION ALL
      SELECT 'allocation',a.id,to_jsonb(a) FROM public.customer_receipt_backoffice_invoice_allocations a
        WHERE a.company_id=c AND a.invoice_id=target_invoice_id) x) IS DISTINCT FROM source_receipts
    OR (SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM public.backoffice_sales_down_payment_applications a
      WHERE a.company_id=c AND a.regular_invoice_id=target_invoice_id) IS DISTINCT FROM source_dp THEN
    RAISE EXCEPTION 'TEST_FAILED: original Receipt or DP records mutated';
  END IF;
  BEGIN
    UPDATE private.backoffice_invoice_revisions SET payable_delta=1 WHERE company_id=c AND id=target_revision_id;
    RAISE EXCEPTION 'TEST_FAILED: revision mutation allowed';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM<>'INVOICE_REVISION_HISTORY_IMMUTABLE' THEN RAISE; END IF;
  END;
  IF has_function_privilege('authenticated','private.execute_backoffice_invoice_revision(uuid)','EXECUTE')
    OR has_table_privilege('authenticated','private.backoffice_invoice_revisions','SELECT') THEN
    RAISE EXCEPTION 'TEST_FAILED: private writer exposed';
  END IF;

  SELECT i.* INTO STRICT amount_invoice FROM public.backoffice_sales_invoices i
    WHERE i.id=NULLIF(current_setting('mads_test.invoice_revision_fixture_2',true),'')::uuid;
  SELECT min(l.id::text)::uuid INTO STRICT amount_line FROM public.backoffice_sales_invoice_lines l
    WHERE l.company_id=c AND l.invoice_id=amount_invoice.id AND l.line_type='PRODUCT'
      AND l.source_kind='SALES_ORDER';
  SELECT count(*) INTO amount_revision FROM public.backoffice_sales_invoice_price_corrections pc
    WHERE pc.company_id=c AND pc.source_invoice_id=amount_invoice.id AND pc.status='POSTED';
  SELECT jsonb_agg(jsonb_build_object('invoiceLineId',l.id,
    'unitPrice',(private.backoffice_invoice_effective_entered_unit_price(c,l.id)
      +CASE WHEN l.id=amount_line THEN 100 ELSE 0 END)::text,
    'discountAmount',(private.backoffice_invoice_effective_line_amounts(c,l.id)->>'discountAmount')) ORDER BY l.id)
  INTO amount_lines FROM public.backoffice_sales_invoice_lines l
  WHERE l.company_id=c AND l.invoice_id=amount_invoice.id AND l.line_type='PRODUCT'
    AND l.source_kind='SALES_ORDER';
  amount_command:=jsonb_build_object('kind','INVOICE_REVISION','invoiceId',amount_invoice.id,
    'operationId',amount_operation,'masterVersion',amount_invoice.master_version,
    'revision',amount_revision,'customerId',amount_invoice.customer_id,
    'invoiceDate',amount_invoice.invoice_date,'dueDate',jsonb_build_object('mode','KEEP_TERM'),
    'lines',amount_lines);
  amount_prepared:=private.prepare_backoffice_invoice_revision(amount_command);
  IF (amount_prepared->'amounts'->>'payableDelta')::numeric<=0 THEN
    RAISE EXCEPTION 'TEST_FAILED: nonzero amount fixture required'; END IF;
  amount_result:=private.execute_backoffice_invoice_revision(amount_operation);
  amount_effective:=private.backoffice_invoice_effective_line_amounts(c,amount_line);
  IF amount_result->>'status' IS DISTINCT FROM 'POSTED'
    OR (amount_result->>'effectiveTotal')::numeric<>(amount_prepared->'amounts'->>'afterTotal')::numeric
    OR (amount_effective->>'enteredUnitPrice')::numeric<>
      (SELECT (element.value->>'unitPrice')::numeric FROM jsonb_array_elements(amount_lines) element(value)
        WHERE element.value->>'invoiceLineId'=amount_line::text)
    OR private.backoffice_invoice_effective_total(c,amount_invoice.id,NULL)<>
      (amount_prepared->'amounts'->>'afterTotal')::numeric THEN
    RAISE EXCEPTION 'TEST_FAILED: amount-changing effective readers mismatch';
  END IF;
  SELECT jsonb_agg(jsonb_build_object('invoiceLineId',l.id,
    'unitPrice',(private.backoffice_invoice_effective_entered_unit_price(c,l.id)
      +CASE WHEN l.id=amount_line THEN 100 ELSE 0 END)::text,
    'discountAmount',(private.backoffice_invoice_effective_line_amounts(c,l.id)->>'discountAmount')) ORDER BY l.id)
  INTO amount_lines FROM public.backoffice_sales_invoice_lines l
  WHERE l.company_id=c AND l.invoice_id=amount_invoice.id AND l.line_type='PRODUCT'
    AND l.source_kind='SALES_ORDER';
  repeat_command:=amount_command||jsonb_build_object('operationId',repeat_operation,'revision',amount_revision+1,
    'lines',amount_lines);
  repeat_prepared:=private.prepare_backoffice_invoice_revision(repeat_command);
  repeat_result:=private.execute_backoffice_invoice_revision(repeat_operation);
  IF (repeat_result->>'revision')::bigint<>2 OR jsonb_array_length(repeat_result->'journalIds')<>1
    OR (repeat_result->>'effectiveTotal')::numeric<>(repeat_prepared->'amounts'->>'afterTotal')::numeric
    OR private.backoffice_invoice_effective_total(c,amount_invoice.id,NULL)<>
      (repeat_prepared->'amounts'->>'afterTotal')::numeric THEN
    RAISE EXCEPTION 'TEST_FAILED: repeat amount-only revision mismatch';
  END IF;
  BEGIN
    repeat_command:=repeat_command||jsonb_build_object('operationId',gen_random_uuid(),
      'customerId',(SELECT id FROM public.customers WHERE company_id=c AND id<>amount_invoice.customer_id
        AND is_active ORDER BY id LIMIT 1),'revision',amount_revision+2);
    PERFORM private.prepare_backoffice_invoice_revision(repeat_command);
    PERFORM private.execute_backoffice_invoice_revision((repeat_command->>'operationId')::uuid);
    RAISE EXCEPTION 'TEST_FAILED: unsupported repeat identity change accepted';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM<>'INVOICE_REVISION_REPEAT_IDENTITY_OR_DATE_NOT_YET_SUPPORTED' THEN RAISE; END IF;
  END;
  SELECT i.* INTO STRICT report_invoice FROM public.backoffice_sales_invoices i
    WHERE i.id=NULLIF(current_setting('mads_test.invoice_revision_fixture_3',true),'')::uuid;
  SELECT id INTO STRICT report_customer FROM public.customers
    WHERE company_id=c AND code='STAGING-REVISION-CUSTOMER' AND is_active;
  SELECT count(*) INTO report_revision FROM public.backoffice_sales_invoice_price_corrections pc
    WHERE pc.company_id=c AND pc.source_invoice_id=report_invoice.id AND pc.status='POSTED';
  SELECT jsonb_agg(jsonb_build_object('invoiceLineId',l.id,
    'unitPrice',(private.backoffice_invoice_effective_entered_unit_price(c,l.id)+100)::text,
    'discountAmount',(private.backoffice_invoice_effective_line_amounts(c,l.id)->>'discountAmount')) ORDER BY l.id)
  INTO report_lines FROM public.backoffice_sales_invoice_lines l
  WHERE l.company_id=c AND l.invoice_id=report_invoice.id AND l.line_type='PRODUCT'
    AND l.source_kind='SALES_ORDER';
  report_command:=jsonb_build_object('kind','INVOICE_REVISION','invoiceId',report_invoice.id,
    'operationId',report_operation,'masterVersion',report_invoice.master_version,
    'revision',report_revision,'customerId',report_customer,'invoiceDate',report_invoice.invoice_date,
    'dueDate',jsonb_build_object('mode','KEEP_TERM'),'lines',report_lines);
  PERFORM private.prepare_backoffice_invoice_revision(report_command);
  report_result:=private.execute_backoffice_invoice_revision(report_operation);
  SET CONSTRAINTS ALL IMMEDIATE;
  SET CONSTRAINTS ALL DEFERRED;
  IF report_result->>'status' IS DISTINCT FROM 'POSTED'
    OR report_result->>'customerId' IS DISTINCT FROM report_customer::text
    OR report_result->>'invoiceDate' IS DISTINCT FROM report_invoice.invoice_date::text THEN
    RAISE EXCEPTION 'TEST_FAILED: current-date customer-only report fixture';
  END IF;
END
$test$;

-- Exercise the canonical Return -> Credit Note path against a POSTED Invoice
-- whose customer and amount were both changed by the unified revision above.
-- Physical stock effects remain owned by the existing Return receipt runtime.
DO $return_credit$
DECLARE
  c constant uuid:='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8'::uuid;
  target_invoice public.backoffice_sales_invoices%rowtype;
  target_line public.backoffice_sales_invoice_lines%rowtype;
  effective_identity jsonb;effective_line jsonb;source_invoice jsonb;source_delivery jsonb;
  v_order_id uuid;v_order_line_id uuid;v_delivery_id uuid;v_return_id uuid;v_return_line_id uuid;
  v_receipt_id uuid;v_receipt_line_id uuid;v_note_id uuid;v_warehouse_id uuid;v_product_id uuid;
  v_version bigint;stock_before numeric;stock_after numeric;result jsonb;retry jsonb;
  allocate_operation uuid:=gen_random_uuid();post_operation uuid:=gen_random_uuid();
  expected_total numeric;note_total numeric;note_customer uuid;note_snapshot jsonb;
  return_status text;expected_return_status text;journal_customer_rows integer;
BEGIN
  SELECT invoice.* INTO STRICT target_invoice
  FROM public.backoffice_sales_invoices invoice
  WHERE invoice.id=NULLIF(current_setting('mads_test.invoice_revision_fixture_3',true),'')::uuid;
  SELECT line.* INTO STRICT target_line
  FROM public.backoffice_sales_invoice_lines line
  WHERE line.company_id=c AND line.invoice_id=target_invoice.id
    AND line.line_type='PRODUCT' AND line.source_kind='SALES_ORDER';
  v_order_id:=target_invoice.sales_order_id;
  v_order_line_id:=target_line.sales_order_line_id;
  v_warehouse_id:=target_invoice.warehouse_id;
  v_product_id:=target_line.product_id;
  effective_identity:=private.backoffice_invoice_effective_identity(c,target_invoice.id,NULL);
  effective_line:=private.backoffice_invoice_effective_line_amounts(c,target_line.id);
  expected_total:=(effective_line->>'lineAmount')::numeric+(effective_line->>'taxAmount')::numeric;
  IF effective_identity->>'customerId'=target_invoice.customer_id::text
    OR (effective_line->>'enteredUnitPrice')::numeric=target_line.unit_price THEN
    RAISE EXCEPTION 'TEST_PRECONDITION_FAILED: revised customer and amount Return fixture required';
  END IF;
  SELECT to_jsonb(invoice) INTO STRICT source_invoice
  FROM public.backoffice_sales_invoices invoice
  WHERE invoice.company_id=c AND invoice.id=target_invoice.id;
  SELECT delivery.id,to_jsonb(delivery) INTO STRICT v_delivery_id,source_delivery
  FROM public.backoffice_sales_delivery_orders delivery
  WHERE delivery.company_id=c AND delivery.sales_order_id=v_order_id;
  SELECT COALESCE(stock.stock_qty,0) INTO stock_before
  FROM public.product_stocks stock
  WHERE stock.company_id=c AND stock.warehouse_id=v_warehouse_id AND stock.product_id=v_product_id;

  result:=public.save_backoffice_sales_return_draft(NULL,NULL,gen_random_uuid(),v_order_id,
    jsonb_build_object('reason','Unified Invoice revision Return behavior',
      'lines',jsonb_build_array(jsonb_build_object('salesOrderLineId',v_order_line_id,
        'quantityUom',target_line.quantity_uom,'reason','Rollback-only revised Invoice Return'))));
  v_return_id:=(result->'data'->>'id')::uuid;
  result:=public.submit_backoffice_sales_return(v_return_id,
    (result->'data'->>'masterVersion')::bigint,gen_random_uuid());
  result:=public.approve_backoffice_sales_return(v_return_id,
    (result->'data'->>'masterVersion')::bigint,gen_random_uuid());
  SELECT line.id INTO STRICT v_return_line_id
  FROM public.backoffice_sales_return_lines line
  WHERE line.company_id=c AND line.return_id=v_return_id AND line.sales_order_line_id=v_order_line_id;
  result:=public.post_backoffice_sales_return_receipt(v_return_id,
    (result->'data'->>'masterVersion')::bigint,gen_random_uuid(),current_date,
    jsonb_build_array(jsonb_build_object('returnLineId',v_return_line_id,
      'quantityUom',target_line.quantity_uom,'warehouseId',v_warehouse_id,
      'disposition','RESTOCK','notes','Unified revision rollback fixture')),
    'Unified Invoice revision Return behavior');
  v_receipt_id:=(result->>'receiptId')::uuid;
  SELECT line.id INTO STRICT v_receipt_line_id
  FROM public.backoffice_sales_return_receipt_lines line
  WHERE line.company_id=c AND line.receipt_id=v_receipt_id AND line.return_line_id=v_return_line_id;
  SELECT document.master_version INTO STRICT v_version
  FROM public.backoffice_sales_returns document
  WHERE document.company_id=c AND document.id=v_return_id;
  result:=public.allocate_backoffice_sales_return_invoices(v_return_id,v_version,allocate_operation,
    jsonb_build_array(jsonb_build_object('returnReceiptLineId',v_receipt_line_id,
      'allocationType','POSTED_INVOICE','invoiceId',target_invoice.id,
      'invoiceLineId',target_line.id,'quantityUom',target_line.quantity_uom)));
  retry:=public.allocate_backoffice_sales_return_invoices(v_return_id,v_version,allocate_operation,
    jsonb_build_array(jsonb_build_object('returnReceiptLineId',v_receipt_line_id,
      'allocationType','POSTED_INVOICE','invoiceId',target_invoice.id,
      'invoiceLineId',target_line.id,'quantityUom',target_line.quantity_uom)));
  IF COALESCE((retry->>'exactRetry')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'TEST_FAILED: revised Invoice Return allocation exact retry';
  END IF;
  SELECT note.id,note.customer_id,note.grand_total,note.source_invoice_snapshot
  INTO STRICT v_note_id,note_customer,note_total,note_snapshot
  FROM public.backoffice_sales_credit_notes note
  WHERE note.company_id=c AND note.return_id=v_return_id
    AND note.source_invoice_id=target_invoice.id AND note.status='DRAFT';
  IF note_customer IS DISTINCT FROM (effective_identity->>'customerId')::uuid
    OR note_total IS DISTINCT FROM expected_total
    OR note_snapshot->'effectiveIdentity' IS DISTINCT FROM effective_identity
    OR NOT EXISTS(SELECT 1 FROM public.backoffice_sales_credit_note_lines line
      WHERE line.company_id=c AND line.credit_note_id=v_note_id
        AND line.source_invoice_line_id=target_line.id
        AND line.quantity_base=target_line.quantity_base
        AND line.unit_price=(effective_line->>'enteredUnitPrice')::numeric
        AND line.line_amount=(effective_line->>'lineAmount')::numeric
        AND line.discount_amount=(effective_line->>'discountAmount')::numeric
        AND line.tax_amount=(effective_line->>'taxAmount')::numeric) THEN
    RAISE EXCEPTION USING MESSAGE='TEST_FAILED: revised Invoice Credit Note identity/amount lineage: '||
      jsonb_build_object('noteCustomer',note_customer,'effectiveIdentity',effective_identity,
        'noteTotal',note_total,'expectedTotal',expected_total,'effectiveLine',effective_line)::text;
  END IF;
  SELECT note.master_version INTO STRICT v_version
  FROM public.backoffice_sales_credit_notes note
  WHERE note.company_id=c AND note.id=v_note_id;
  result:=public.post_backoffice_sales_credit_note(v_note_id,v_version,post_operation);
  retry:=public.post_backoffice_sales_credit_note(v_note_id,v_version,post_operation);
  expected_return_status:=CASE WHEN (result->'data'->>'refundLiabilityAmount')::numeric>0
    THEN 'REFUND_PENDING' ELSE 'COMPLETED' END;
  SELECT document.status INTO STRICT return_status
  FROM public.backoffice_sales_returns document
  WHERE document.company_id=c AND document.id=v_return_id;
  SELECT count(*) INTO journal_customer_rows
  FROM public.finance_journals journal
  JOIN public.finance_journal_lines line ON line.company_id=journal.company_id
    AND line.journal_id=journal.id
  WHERE journal.company_id=c AND journal.source_type='backoffice_sales_credit_notes'
    AND journal.source_id=v_note_id AND journal.status='POSTED'
    AND line.customer_id=(effective_identity->>'customerId')::uuid;
  SELECT stock.stock_qty INTO STRICT stock_after
  FROM public.product_stocks stock
  WHERE stock.company_id=c AND stock.warehouse_id=v_warehouse_id AND stock.product_id=v_product_id;
  IF result->'data'->>'status' IS DISTINCT FROM 'POSTED'
    OR COALESCE((retry->>'exactRetry')::boolean,false) IS NOT TRUE
    OR NOT EXISTS(SELECT 1 FROM public.backoffice_sales_credit_notes note
      WHERE note.company_id=c AND note.id=v_note_id AND note.status='POSTED'
        AND note.customer_id=(effective_identity->>'customerId')::uuid)
    OR (result->'data'->>'grandTotal')::numeric IS DISTINCT FROM expected_total
    OR (result->'data'->>'arReductionAmount')::numeric
      +(result->'data'->>'refundLiabilityAmount')::numeric IS DISTINCT FROM expected_total
    OR return_status IS DISTINCT FROM expected_return_status
    OR journal_customer_rows<1
    OR stock_after-stock_before IS DISTINCT FROM target_line.quantity_base
    OR (SELECT to_jsonb(invoice) FROM public.backoffice_sales_invoices invoice
      WHERE invoice.company_id=c AND invoice.id=target_invoice.id) IS DISTINCT FROM source_invoice
    OR (SELECT to_jsonb(delivery) FROM public.backoffice_sales_delivery_orders delivery
      WHERE delivery.company_id=c AND delivery.id=v_delivery_id) IS DISTINCT FROM source_delivery THEN
    RAISE EXCEPTION USING MESSAGE='TEST_FAILED: revised Invoice Return/Credit Note posting: '||
      jsonb_build_object('result',result,'retry',retry,'returnStatus',return_status,
        'journalCustomerRows',journal_customer_rows,'stockDelta',stock_after-stock_before)::text;
  END IF;
END
$return_credit$;
DO $auth_fixture$
DECLARE
  v_invoice_id uuid;v_command jsonb;v_prior_customer uuid;v_new_customer uuid;
  v_report_identity jsonb;v_report_source jsonb;v_customer_name text;v_effective_total numeric;
BEGIN
  SELECT p.invoice_id,p.request_snapshot||jsonb_build_object('operationId',p.operation_id)
  INTO STRICT v_invoice_id,v_command
  FROM private.backoffice_invoice_revision_preparations p
  WHERE p.invoice_id=NULLIF(current_setting('mads_test.invoice_revision_fixture_2',true),'')::uuid
  ORDER BY p.created_at DESC LIMIT 1;
  PERFORM set_config('mads_test.auth_invoice',v_invoice_id::text,true);
  PERFORM set_config('mads_test.auth_command',v_command::text,true);

  SELECT r.invoice_id,r.prior_customer_id,r.new_customer_id,
    private.backoffice_invoice_effective_identity(r.company_id,r.invoice_id,current_date),
    to_jsonb(invoice),customer.name,
    private.backoffice_invoice_effective_total(r.company_id,r.invoice_id,current_date)
  INTO STRICT v_invoice_id,v_prior_customer,v_new_customer,v_report_identity,
    v_report_source,v_customer_name,v_effective_total
  FROM private.backoffice_invoice_revisions r
  JOIN public.backoffice_sales_invoices invoice ON invoice.company_id=r.company_id AND invoice.id=r.invoice_id
  JOIN public.customers customer ON customer.company_id=r.company_id AND customer.id=r.new_customer_id
  WHERE r.company_id='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8'::uuid
    AND r.prior_customer_id<>r.new_customer_id AND r.new_invoice_date<=current_date
  ORDER BY r.posted_at DESC,r.id LIMIT 1;
  PERFORM set_config('mads_test.report_invoice',v_invoice_id::text,true);
  PERFORM set_config('mads_test.report_prior_customer',v_prior_customer::text,true);
  PERFORM set_config('mads_test.report_new_customer',v_new_customer::text,true);
  PERFORM set_config('mads_test.report_identity',v_report_identity::text,true);
  PERFORM set_config('mads_test.report_source',v_report_source::text,true);
  PERFORM set_config('mads_test.report_customer_name',v_customer_name,true);
  PERFORM set_config('mads_test.report_effective_total',v_effective_total::text,true);
END
$auth_fixture$;
SET LOCAL ROLE authenticated;
DO $authenticated$
DECLARE c uuid:='4eedbf12-3c60-40e0-b2b7-1a48ca62b6f8';target_invoice uuid;command jsonb;
 operation uuid;result jsonb;context jsonb;ui jsonb;payment jsonb;
 report_invoice uuid;old_customer uuid;new_customer uuid;new_statement jsonb;old_statement jsonb;aging jsonb;
 report_identity jsonb;report_source jsonb;
 report_customer_name text;report_effective_total numeric;export_payload jsonb;export_invoice jsonb;
 new_statement_hits integer;old_statement_hits integer;
BEGIN
 SELECT NULLIF(current_setting('mads_test.auth_invoice',true),'')::uuid,
   (NULLIF(current_setting('mads_test.auth_command',true),'')::jsonb->>'operationId')::uuid,
   NULLIF(current_setting('mads_test.auth_command',true),'')::jsonb
 INTO STRICT target_invoice,operation,command;
 result:=public.post_backoffice_invoice_revision(command);
 context:=public.get_backoffice_invoice_revision_context(target_invoice);
 ui:=public.get_backoffice_sales_invoice_ui(target_invoice);
 payment:=public.get_backoffice_sales_invoice_payment_context(target_invoice);
 SELECT NULLIF(current_setting('mads_test.report_invoice',true),'')::uuid,
   NULLIF(current_setting('mads_test.report_prior_customer',true),'')::uuid,
   NULLIF(current_setting('mads_test.report_new_customer',true),'')::uuid,
   NULLIF(current_setting('mads_test.report_identity',true),'')::jsonb,
   NULLIF(current_setting('mads_test.report_source',true),'')::jsonb,
   current_setting('mads_test.report_customer_name',true),
   NULLIF(current_setting('mads_test.report_effective_total',true),'')::numeric
 INTO STRICT report_invoice,old_customer,new_customer,report_identity,report_source,
   report_customer_name,report_effective_total;
 new_statement:=public.get_finance_customer_statement(new_customer,DATE '2000-01-01',current_date,NULL);
 old_statement:=public.get_finance_customer_statement(old_customer,DATE '2000-01-01',current_date,NULL);
 aging:=public.get_finance_ar_aging(current_date,new_customer,NULL);
 export_payload:=public.export_sales_documents(DATE '2000-01-01',current_date);
 SELECT element.value INTO STRICT export_invoice FROM jsonb_array_elements(export_payload->'invoices') element(value)
   WHERE element.value->>'invoiceId'=report_invoice::text;
 SELECT count(*) INTO new_statement_hits FROM jsonb_array_elements(new_statement->'rows') row(value)
   WHERE row.value->>'sourceId'=report_invoice::text;
 SELECT count(*) INTO old_statement_hits FROM jsonb_array_elements(old_statement->'rows') row(value)
   WHERE row.value->>'sourceId'=report_invoice::text;
 IF result->>'exactRetry' IS DISTINCT FROM 'true' OR (context->>'revision')::bigint<2
   OR jsonb_array_length(context->'history')<>2
   OR jsonb_array_length(context->'lines')<1
   OR context->>'effectiveTotal' IS DISTINCT FROM result->>'effectiveTotal'
   OR ui->'data'->>'customerId' IS DISTINCT FROM context->'effectiveIdentity'->>'customerId'
   OR ui->'data'->>'invoiceDate' IS DISTINCT FROM context->'effectiveIdentity'->>'invoiceDate'
   OR ui->'data'->>'effectiveGrandTotal' IS DISTINCT FROM context->>'effectiveTotal'
   OR payment->'effectiveIdentity' IS DISTINCT FROM context->'effectiveIdentity'
   OR payment->>'invoiceRevision' IS DISTINCT FROM context->>'revision'
   OR new_statement_hits<>1
   OR old_statement_hits<>0
   OR aging->>'companyId' IS NULL
   OR export_invoice->>'customerName' IS DISTINCT FROM report_customer_name
   OR export_invoice->>'invoiceDate' IS DISTINCT FROM report_identity->>'invoiceDate'
   OR (export_invoice->>'grandTotal')::numeric IS DISTINCT FROM report_effective_total
   OR NOT has_function_privilege('authenticated','public.post_backoffice_invoice_revision(jsonb)','EXECUTE')
   OR NOT has_function_privilege('authenticated','public.get_backoffice_invoice_revision_context(uuid)','EXECUTE') THEN
  RAISE EXCEPTION USING MESSAGE='TEST_FAILED: authenticated unified RPC/context contract: '||
    jsonb_build_object('exactRetry',result->>'exactRetry','contextRevision',context->>'revision',
      'historyRows',jsonb_array_length(context->'history'),'lineRows',jsonb_array_length(context->'lines'),
      'contextTotal',context->>'effectiveTotal','resultTotal',result->>'effectiveTotal',
      'uiCustomer',ui->'data'->>'customerId','contextCustomer',context->'effectiveIdentity'->>'customerId',
      'uiDate',ui->'data'->>'invoiceDate','contextDate',context->'effectiveIdentity'->>'invoiceDate',
      'uiTotal',ui->'data'->>'effectiveGrandTotal','paymentRevision',payment->>'invoiceRevision',
      'paymentIdentity',payment->'effectiveIdentity','newStatementHits',new_statement_hits,
      'oldStatementHits',old_statement_hits,'agingCompany',aging->>'companyId',
      'reportInvoice',report_invoice,'reportIdentity',report_identity,
      'reportSourceStatus',report_source->>'status','reportSourceDate',report_source->>'invoice_date',
      'exportInvoice',export_invoice,'reportCustomerName',report_customer_name,
      'reportEffectiveTotal',report_effective_total,
      'newStatementRows',new_statement->'rows')::text; END IF;
END
$authenticated$;
